function cachedFetch(cacheKey, id, fetchFn) {
    var CACHE_EXPIRY = 30 * 60 * 1000;
    var cached = getMyVar(cacheKey, '');
    if (cached) {
        try {
            var data = JSON.parse(cached);
            if (data.id === id && data.ts && (Date.now() - data.ts < CACHE_EXPIRY)) {
                return data.data;
            }
        } catch (e) {}
    }
    var result = fetchFn();
    if (result) {
        putMyVar(cacheKey, JSON.stringify({ id: id, ts: Date.now(), data: result }));
    }
    return result;
}

function setProgress(id, progress) {
    try {
        var historyData = {};
        try {
            var historyContent = readFile('progress_history.json', 0);
            if (historyContent) historyData = JSON.parse(historyContent);
        } catch (e) {}
        var existing = historyData[id] || {};
        progress.lastPlayTime = Date.now();
        if (!progress.playLink && existing.playLink) progress.playLink = existing.playLink;
        if (!progress.playType && existing.playType) progress.playType = existing.playType;
        historyData[id] = progress;
        var thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
        for (var key in historyData) {
            if (historyData[key] && historyData[key].lastPlayTime && historyData[key].lastPlayTime < thirtyDaysAgo) {
                delete historyData[key];
            }
        }
        saveFile('progress_history.json', JSON.stringify(historyData), 0);
    } catch (e) {}
}

