function playBocaiEpisode(doubanId, sourceTitle, episodeIndex, episodeTitle, rawPlayLink, movieTitle, preTag) {
    setProgress(doubanId, { sourceTitle: sourceTitle, episodeIndex: episodeIndex, episodeTitle: episodeTitle, playLink: rawPlayLink, playType: 'bocai' });
    fpUpdate(doubanId, sourceTitle, episodeIndex, episodeTitle, rawPlayLink, 'bocai');
    var dmMode = getExternalDanmuConfig().mode;
    if (/\[画\]/.test(sourceTitle) || /\[音\]/.test(sourceTitle) || /\[书\]/.test(sourceTitle)) dmMode = 'off';
    var dmPath = (dmMode === 'external' || dmMode === 'local') ? getExternalDanmuUrl(rawPlayLink, movieTitle || '', '', episodeTitle) : '';
    var dmSource = dmPath ? (dmMode === 'local' ? '本地弹幕' : '外接弹幕') : '';
    var dmCacheKey = 'dm_url_' + doubanId + '_' + episodeIndex;
    var dmCached = dmMode === 'box' ? getMyVar(dmCacheKey, '') : '';
    if (dmCached) {
        try {
            var dmData = JSON.parse(dmCached);
            if (dmData.ts && (Date.now() - dmData.ts < 2 * 60 * 60 * 1000) && dmData.url) {
                dmPath = dmData.url;
                putVar('dm_share', dmPath);
                var result = { urls: ['video://' + rawPlayLink + '#isVideo=true#' + (preTag || '')] };
                result.danmu = dmPath;
                log('弹幕获取完毕[' + (dmSource || '弹幕盒子') + ']');
                return JSON.stringify(result);
            }
        } catch (e) {}
    }
    if (dmMode === 'box') try {
        var eps = getEpisodes(doubanId);
        if (eps && eps.playList && eps.playList.length > 0) {
            var matchedUrl = '';
            for (var i = 0; i < eps.playList.length; i++) {
                var list = eps.playList[i].list;
                if (episodeIndex < list.length) {
                    matchedUrl = list[episodeIndex].play_link;
                    break;
                }
            }
            if (!matchedUrl) {
                var lastSrc = eps.playList[eps.playList.length - 1];
                matchedUrl = lastSrc.list[lastSrc.list.length - 1].play_link;
            }
            if (matchedUrl) {
                try {
                    var dmFun = $.require('hiker://page/dmFun?rule=dm盒子');
                    var dm = dmFun.dmRoute(matchedUrl);
                    if (dm && dm !== false) {
                        dmPath = dm;
                        dmSource = '弹幕盒子';
                        putVar('dm_share', dm);
                        putMyVar(dmCacheKey, JSON.stringify({ url: dm, ts: Date.now() }));
                    }
                } catch (e) {}
            }
        }
    } catch (e) {}
    if (dmPath) putVar('dm_share', dmPath);
    var result = { urls: ['video://' + rawPlayLink + '#isVideo=true#' + (preTag || '')] };
    if (dmPath) {
        result.danmu = dmPath;
        log('弹幕获取完毕[' + (dmSource || '弹幕盒子') + ']');
    }
    return JSON.stringify(result);
}

function getDoubanRes(url) {
    var cc = null;
    if ($.type(url) == 'object') {
        cc = url.cc;
        url = url.url;
    }
    var _url = url;
    if (url.indexOf('apikey') === -1) {
        _url += (url.indexOf('?') === -1 ? '?' : '&') + "apikey=0dad551ec0f84ed02907ff5c42e8ec70";
    }
    _url += '&loc_id=108288';
    var _ts = parseInt(Date.now() / 1000).toString();
    var m = 'GET&' + encodeURIComponent(url.split('douban.com')[1].split('?')[0]) + '&' + _ts;
