        .replace(/[（(][^）)]*(?:4K|8K|1080|720|2160|HDR|HD|臻彩|杜比|高码|中字|国语)[^）)]*[）)]/gi, '')
        .replace(/\s+/g, '')
        .trim();
}

function isCollectionTitle(title) {
