function filterPanPlayUrlByTitle(playUrl, movieName) {
    if (!playUrl) return playUrl;
    var norm = normalizeTitle(movieName);
    var baseKey = normalizeSearchText(norm.baseName || norm.cleanName);
    if (!baseKey) return playUrl;
    var parts = playUrl.split('#').filter(function(e) { return e; });
    var kept = [];
    for (var i = 0; i < parts.length; i++) {
        var title = (parts[i].split('$')[0] || '').trim();
        var titleKey = normalizeSearchText(title);
        if (!titleKey || titleKey.indexOf(baseKey) === -1) continue;
        if (norm.seasonInfo && !matchSeasonInfo(movieName, title)) continue;
        if (norm.seasonInfo && isCollectionTitle(title)) continue;
        kept.push(parts[i]);
    }
    return kept.join('#');
