                                var sr = cr2.executeSearch(obj.rule, obj.searchKeys[si], 1, { silentVerify: true });
                                if (sr && sr.length > 0) { customResults = sr; break; }
                            } catch(e) {}
                        }
                        if (!customResults || customResults.length === 0) return results;
                        for (var vi = 0; vi < customResults.length; vi++) {
