                            if (getPanType(customResults[hp].url || '')) { hasPanUrl = true; break; }
                        }
                        if (hasPanUrl) {
                            var panTypeGroups = {};
                            var matchedPanItems = [];
                            for (var cj = 0; cj < customResults.length; cj++) {
