                                var crPwd = crItem.password || '';
                                var crTitle = crItem.title || '';
                                if (isPanBlocked(crTitle)) continue;
                                var pt = getPanType(crUrl);
                                if (!pt) continue;
                                if (obj.ruleName && obj.ruleName.indexOf('[盘]') !== -1 && ['baidu','quark','xunlei','uc','123','magnet'].indexOf(pt.type) === -1) continue;
                                var item = { title: crTitle, url: crUrl, pwd: crPwd, type: pt.type };
