                            }
                            var finalPanItems = matchedPanItems;
                            for (var ci2 = 0; ci2 < finalPanItems.length; ci2++) {
                                var fi = finalPanItems[ci2];
                                if (!panTypeGroups[fi.type]) panTypeGroups[fi.type] = [];
                                var crData = base64Encode(JSON.stringify({url: fi.url, password: fi.pwd, type: fi.type}));
                                panTypeGroups[fi.type].push(fi.title + '$' + crData);
                            }
                            var ptKeys = Object.keys(panTypeGroups);
                            for (var ptk = 0; ptk < ptKeys.length; ptk++) {
                                var ptUrls = panTypeGroups[ptKeys[ptk]];
                                if (ptUrls.length > 0) {
                                    results.push({
                                        name: "\uD83D\uDD0D" + obj.ruleName,
                                        key: "custom_" + obj.ruleId + "_" + ptKeys[ptk],
                                        type: "pan",
                                        panType: ptKeys[ptk],
                                        epCount: ptUrls.length,
