                                        siteKey: "custom_" + obj.ruleId,
                                        ruleName: obj.ruleName
                                    });
                                }
                            }
                        } else {
                            var hasSeasonInSearch2 = obj.seasonInfo !== null;
                            for (var cj = 0; cj < customResults.length; cj++) {
                                var vr = customResults[cj];
                                if (vr && vr.playUrl) {
                                    var vrTitle = (vr.title || vr.name || '').replace(/\s+/g, '');
                                    if (hasSeasonInSearch2 && vrTitle && !matchSeasonInfo(obj.movieName, vrTitle)) continue;
                                    results.push({
