                    } catch(e2) {}
                    return results;
                },
                param: { rule: rule, ruleId: rule.id, ruleName: rule.name, searchKeys: (rule.name && rule.name.indexOf('[盘]') !== -1 && norm.baseName && norm.baseName !== norm.cleanName) ? [norm.baseName, norm.cleanName] : searchKeys, cleanName: norm.cleanName, baseName: norm.baseName, seasonInfo: norm.seasonInfo },
                id: 'rule_' + rule.id
