var SOURCE_PRIORITY = { '腾讯视频': 1, '爱奇艺视频': 2, '优酷视频': 3, '芒果TV': 4, '哔哩哔哩': 5 };

function getEpisodes(doubanId) {
    try {
        var cacheKey = 'ep_cache_' + doubanId;
        var cached = getMyVar(cacheKey, '');
        if (cached) {
            try {
                var data = JSON.parse(cached);
                if (data.ts && (Date.now() - data.ts < 2 * 60 * 60 * 1000)) {
                    return data.data;
                }
            } catch (e) {}
        }
        var cookieCache = 'hiker://files/cache/doubancookie.txt';
        var headers = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" };
        if (fileExist(cookieCache)) {
            headers["Cookie"] = fetch(cookieCache);
        }
        var html = fetch('https://movie.douban.com/subject/' + doubanId + '/', { headers: headers });
        if (!html) return { update: '获取失败', playList: null };
        var sources_list = html.match(/sources\[(1|3|7|8|9|17)\][\s\S]*?\]/g);
        if (!sources_list) {
            var script_list = parseDomForArray(html, 'body&&script[src]');
            var sources_url = '';
            for (var i in script_list) {
                var url = parseDomForHtml(script_list[i], 'script&&src');
                if (url.indexOf('mixed_static') !== -1) sources_url = url;
            }
            if (sources_url) {
                sources_list = request(sources_url).match(/sources\[(1|3|7|8|9|17)\][\s\S]*?\]/g);
            }
        }
        var sources_title = ['', '腾讯视频', '', '优酷视频', '', '', '', '芒果TV', '哔哩哔哩', '爱奇艺视频', '', '', '', '', '', '', '', '西瓜视频'];
        if (!sources_list) return { update: '暂时未获取到更新情况', playList: null };
        var sources = {};
        sources_list.map(function(item) { eval(unescape(item)); });
        var playList = [];
        for (var i in sources) {
            if (sources[i] != null) {
                playList.push({
                    title: sources_title[i],
                    list: sources[i].map(function(item) {
                        return {
                            play_link: parseQueryString(item.play_link).url,
                            ep: '第' + item.ep + '集',
                            epNum: Number(item.ep)
                        };
                    })
                });
            }
        }
        playList.sort(function(a, b) {
            var pa = SOURCE_PRIORITY[a.title] || 99;
            var pb = SOURCE_PRIORITY[b.title] || 99;
            return pa - pb;
        });
        var update = playList.map(function(item) {
            return item.title + '更新至' + item.list[item.list.length - 1].ep;
        }).join('｜');
        var result = { update: update, playList: playList };
        putMyVar(cacheKey, JSON.stringify({ ts: Date.now(), data: result }));
        return result;
    } catch (e) {
        log('getEpisodes失败: ' + e.message);
        return { update: '获取失败', playList: null };
    }
}

