}

function cleanDanmuKeyword(title) {
    var s = String(title || '');
    if (!s) return '';
    // 括号内清晰度/年份/标签
    s = s.replace(/[【\[\(（][^】\]\)）]*(?:4K|8K|1080P?|2160P?|720P?|HDR|HDR10|杜比|臻彩|高码|国语|粤语|日语|英语|中字|双语|港版|台版|抢先|未删减|导演剪辑|加长|无删减|Remastered|重制|修复|BluRay|WEB[- ]?DL|WEBRip|HDTV|BDRip|DVDRip)[^】\]\)）]*[】\]\)）]/gi, '');
    s = s.replace(/[【\[\(（]\s*(19|20)\d{2}\s*[】\]\)）]/g, '');
    // 副标题
    s = s.replace(/\s*[:：\-–—]\s*.+$/, '');
    // 季号 / Season / 第X季 / X季 / X部
    s = s.replace(/\bSeason\s*\d+\b/gi, '');
    s = s.replace(/\bS0*\d+(?:E0*\d+)?\b/gi, '');
    s = s.replace(/第\s*[一二三四五六七八九十百千0-9]+\s*[季部]/g, '');
    s = s.replace(/[一二三四五六七八九十0-9]+\s*[季部]/g, '');
    // 尾部年份
    s = s.replace(/\s*[\(（\[【]?\s*(19|20)\d{2}\s*[\)）\]】]?\s*$/, '');
    // 常见清晰度/语言尾标（未在括号里）
    s = s.replace(/\b(4K|8K|1080P?|2160P?|720P?|HDR|HDR10|杜比|臻彩|高码|国语|粤语|日语|英语|中字|双语|港版|台版|抢先|未删减|导演剪辑|加长|无删减|Remastered|重制|修复|BluRay|WEB[- ]?DL|WEBRip|HDTV|BDRip|DVDRip)\b/gi, '');
    // 全角空格 & 多空白
    s = s.replace(/\s+/g, ' ').trim();
    // 去掉首尾多余标点
    s = s.replace(/^[\s\-·•_,.。、]+|[\s\-·•_,.。、]+$/g, '');
    return s || String(title || '');
}

function getExternalDanmuUrl(playLink, title, fileName, episodeTitle) {
    var config = getExternalDanmuConfig();
    var dmLabel = config.mode === 'local' ? '本地弹幕' : '外接弹幕';
    try { log('【' + dmLabel + '调试】mode=' + config.mode + ' sources=' + config.sources.length + ' title=' + (title || '') + ' fileName=' + (fileName || '') + ' episode=' + (episodeTitle || '')); } catch (e) {}
    if (config.mode !== 'external' && config.mode !== 'local') return '';
    var base;
    if (config.mode === 'local') {
        base = 'http://localhost:9321';
        try {
            var test = JSON.parse(fetch(base + '/api/config', {timeout: 2000}) || '{}');
            if (!test || !test.repository || test.repository.indexOf('danmu_api') < 0) return '';
        } catch(e) { return ''; }
    } else {
        if (config.sources.length === 0) return '';
        base = config.sources[0].url.replace(/\/$/, '');
    }
    if (fileName) {
        var matchText = fileName + (config.platform ? ' @' + config.platform : '');
        try {
            var matchedRaw = fetch(base + '/api/v2/match', { method: 'POST', body: JSON.stringify({ fileName: matchText }), headers: { 'Content-Type': 'application/json' }, timeout: config.timeout }) || '';
            var matched = JSON.parse(matchedRaw || '{}');
            try { log('【' + dmLabel + '文件匹配】keyword=' + matchText + ' matches=' + ((matched.matches || []).length)); } catch (e) {}
            if (matched.matches && matched.matches[0] && matched.matches[0].episodeId) return saveExternalDanmuJson(base + '/api/v2/comment/' + matched.matches[0].episodeId + '?format=json', config, matched.matches[0].episodeId);
        } catch (e) { try { log('【' + dmLabel + '文件匹配异常】' + e.message); } catch (ignore) {} }
    } else if (/^https?:\/\/(?:[^/]+\.)?(?:iqiyi\.com|v\.qq\.com|youku\.com|mgtv\.com|bilibili\.com|miguvideo\.com|sohu\.com|le\.com|pptv\.com)\//i.test(playLink || '')) {
        try { log('【' + dmLabel + '官方链接】' + playLink); } catch (e) {}
        return saveExternalDanmuJson(base + '/api/v2/comment?url=' + encodeURIComponent(playLink) + '&format=json', config, encodeURIComponent(playLink));
    } else if (title) {
        var episodeMatch = String(episodeTitle || '').match(/(?:第\s*)?(\d+)(?:\s*[集话期章])?/);
        var episode = episodeMatch ? String(parseInt(episodeMatch[1], 10)) : (episodeTitle || '');
        var searchAnime = cleanDanmuKeyword(title);
        try {
            var searchUrl = base + '/api/v2/search/episodes?anime=' + encodeURIComponent(searchAnime) + (episode ? '&episode=' + encodeURIComponent(episode) : '');
            var searchRaw = fetch(searchUrl, { timeout: config.timeout }) || '';
            try { log('【' + dmLabel + '搜索响应】url=' + searchUrl + ' length=' + searchRaw.length + ' body=' + searchRaw.substring(0, 200)); } catch (e) {}
            var searchData = JSON.parse(searchRaw || '{}');
            var candidates = [];
            (searchData.animes || []).forEach(function(anime) { (anime.episodes || []).forEach(function(ep) { candidates.push(ep); }); });
            if (config.platform) {
                var preferred = candidates.filter(function(ep) { return String(ep.episodeTitle || '').toLowerCase().indexOf(config.platform.toLowerCase()) >= 0; });
                if (preferred.length) candidates = preferred;
            }
            try { log('【' + dmLabel + '剧集搜索】title=' + title + ' anime=' + searchAnime + ' episode=' + episode + ' matches=' + candidates.length); } catch (e) {}
            if (candidates[0] && candidates[0].episodeId) return saveExternalDanmuJson(base + '/api/v2/comment/' + candidates[0].episodeId + '?format=json', config, candidates[0].episodeId);
        } catch (e) { try { log('【' + dmLabel + '剧集搜索异常】' + e.message); } catch (ignore) {} }
    }
    try { log('【' + dmLabel + '结果】未匹配到弹幕'); } catch (e) {}
    return '';
}

function parseWithConfig(playLink, danmaku, title, episodeTitle) {
    log('【解析调用】来源: ' + (danmaku ? '官方源' : '嗅探/其他') + ' | 链接: ' + playLink.substring(0, 60));
    var parses = [];
    try {
        parses = getXjBase().parses || [];
    } catch (e) {
        parses = [];
    }
    var enabledParse = parses.filter(function(p) { return p.enabled !== false; });
    var defaultHeaders = { "Referer": playLink, "User-Agent": "Mozilla/5.0" };
    var dmMode = getExternalDanmuConfig().mode;
    if (/\[画\]/.test(title) || /\[音\]/.test(title) || /\[书\]/.test(title)) dmMode = 'off';
    var externalDm = (dmMode === 'external' || dmMode === 'local') ? getExternalDanmuUrl(playLink, title, '', episodeTitle) : '';
    var dmPath = dmMode === 'off' ? '' : externalDm;
    var dmSource = externalDm ? (dmMode === 'local' ? '本地弹幕' : '外接弹幕') : '';
    if (!dmPath && dmMode === 'box') {
        try {
            var dmFun = $.require('hiker://page/dmFun?rule=dm盒子');
            dmPath = dmFun.dmRoute(playLink);
            if (dmPath === false) dmPath = getVar('dm_share') || "";
            if (dmPath) dmSource = '弹幕盒子';
        } catch (e) {
            dmPath = getVar('dm_share') || "";
            if (dmPath) dmSource = '弹幕盒子';
        }
    }
    if (dmPath) log('弹幕获取完毕[' + (dmSource || '弹幕盒子') + ']');

    if (enabledParse.length === 0) {
        if (parses.length === 0) {
            return 'toast://⚠️ 未配置解析接口，请先在解析管理页面添加解析';
        }
        return JSON.stringify({
            names: ["默认嗅探"],
            urls: ["video://" + playLink + "#isVideo=true#"],
            danmu: dmPath,
            headers: [defaultHeaders]
        });
    }

    function extractUserJs(jsCode) {
        if (!jsCode || !jsCode.trim()) return "";
        try {
            var parsed = JSON.parse(jsCode);
            if (parsed.js) return parsed.js;
        } catch (e) {}
        return jsCode;
    }

    var names = [];
    var urls = [];
    var headers = [];
    var extras = [];

    for (var i = 0; i < enabledParse.length; i++) {
        var p = enabledParse[i];

        if (p.type === "X") {
            names.push(p.name + " [W]");
            urls.push("video://" + p.url + playLink + "#isVideo=true#");
            headers.push(defaultHeaders);
            extras.push({
                blockRules: ['*.png', '*.jpg', '*.gif', '*.css', '*ads*'],
                cacheM3u8: true
            });
            continue;
        }

        if (p.type === "J") {
            var userJs = extractUserJs(p.jsCode || "");
            if (!userJs) continue;
            names.push(p.name + " [JS]");
            urls.push("webRule://" + p.url + playLink + "#isVideo=true#@" + userJs);
            headers.push(defaultHeaders);
            extras.push({
                blockRules: ['*.png', '*.jpg', '*.gif', '*.css', '*ads*'],
                cacheM3u8: true
            });
            continue;
        }

        if (p.type === "Z") {
            try {
                var res = fetch(p.url + playLink);
                if (!res || res.trim() === '') continue;
                var json = JSON.parse(res);
                var val = null;
                if (p.Names && p.Names.trim()) {
                    val = p.Names.split('.').reduce(function(obj, key) {
                        return (obj && obj[key] ? obj[key] : null);
                    }, json);
                }
                if (!val) val = json.url;
                if (typeof val !== 'string' || !val.trim()) continue;
                var directUrl = val.trim().startsWith('//') ? 'https:' + val.trim() : val.trim();
                if (!directUrl.startsWith('http')) continue;

                var isYouku = (json.msg && json.msg.includes('优酷直连')) || isYoukuDirectLink(directUrl);
                var isM3u8 = directUrl.includes('m3u8');
                var finalUrlToPlay = directUrl;
                var finalHeaders = defaultHeaders;

                if (isYouku && isM3u8) {
                    var youkuHeaders = {
                        'User-Agent': 'Mozilla/5.0 (Linux; Android 12; SM-G998B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.5845.92 Mobile Safari/537.36 YKApp/9.8.0 (Youku)',
                        'Referer': playLink
                    };
                    try {
                        var randomFileName = 'm3u8_' + Date.now() + '_' + Math.random().toString(36).substring(2) + '.m3u8';
                        var cachedPath = cacheM3u8(directUrl, youkuHeaders, randomFileName);
                        if (cachedPath && cachedPath.startsWith('file://')) {
                            finalUrlToPlay = cachedPath.split('##')[0];
                            finalHeaders = {};
                        } else {
                            finalHeaders = youkuHeaders;
                        }
                    } catch (e) {
                        finalHeaders = youkuHeaders;
                    }
                }

                var playerUrl;
                if (finalUrlToPlay.startsWith('file://') && isM3u8) {
                    playerUrl = "video://" + finalUrlToPlay + "#isVideo=true#";
                } else {
                    playerUrl = finalUrlToPlay + '#original=' + encodeURIComponent(playLink) + "&url=" + playLink;
                }

                names.push(p.name + " [解]");
                urls.push(playerUrl);
                headers.push(finalHeaders);
                extras.push({});
            } catch (e) {
                log('【JSON直链】解析失败: ' + e.message);
                continue;
            }
            continue;
        }
    }

    if (names.length === 0) {
        return JSON.stringify({
            names: ["默认嗅探"],
            urls: ["video://" + playLink + "#isVideo=true#"],
            danmu: dmPath,
            headers: [defaultHeaders],
            extras: [{}]
        });
    }

    return JSON.stringify({
        names: names,
        urls: urls,
        danmu: dmPath,
        headers: headers,
        extras: extras
    });
}

