function renderPagination(d, objId, markerPrefix, totalPages, currentPage, sortOrder, totalItems) {
    if (totalPages <= 1) return;
    var epOrderKey = markerPrefix + '_order_' + objId;
    var epPageKey = markerPrefix + '_ep_page_' + objId;
    var orderLabel = sortOrder === 'desc' ? '倒序' : '正序';
    var pageSize = getPageSize();
    var hasPrev = currentPage > 0;
    var hasNext = currentPage < totalPages - 1;
    d.push({ title: hasPrev ? '上一页' : '.', col_type: 'text_4', url: hasPrev ? $('#noLoading#').lazyRule(function(key, cur) { putMyVar(key, String(cur - 1)); refreshPage(false); return 'hiker://empty'; }, epPageKey, currentPage) : 'hiker://empty', extra: { cls: markerPrefix + '_ep', id: markerPrefix + '_pagination' } });
    d.push({ title: '第' + (currentPage + 1) + '/' + totalPages + '页 [\u2018\u2018' + orderLabel + '\u2019\u2019]', col_type: 'text_2', url: 'hiker://empty', extra: { cls: markerPrefix + '_ep' } });
    d.push({ title: hasNext ? '下一页' : '.', col_type: 'text_4', url: hasNext ? $('#noLoading#').lazyRule(function(key, cur) { putMyVar(key, String(cur + 1)); refreshPage(false); return 'hiker://empty'; }, epPageKey, currentPage) : 'hiker://empty', extra: { cls: markerPrefix + '_ep' } });
    if (totalPages > 1) {
        for (var pi = 0; pi < totalPages; pi++) {
            var rangeStart = pi * pageSize + 1;
            var rangeEnd = Math.min((pi + 1) * pageSize, totalItems || totalPages * pageSize);
            var isCurrentRange = (pi === currentPage);
            d.push({
                title: isCurrentRange ? '\u2018\u2018\u2019\u2019<b><font color="#FF5D50">' + rangeStart + '-' + rangeEnd + '</font></b>' : '\u2018\u2018\u2019\u2019' + rangeStart + '-' + rangeEnd,
