function normalizeTitle(title) {
    var cleanName = (title || '').replace(/\s+/g, '').trim();
    var baseName = cleanName;
    baseName = baseName.replace(/第[一二三四五六七八九十百千\d]+[季部集期]/gi, '');
    baseName = baseName.replace(/[季部集期]\d+/g, '');
    baseName = baseName.replace(/年番\d*/g, '');
    baseName = baseName.replace(/\bS\d+\s*(E\d+)?\b/gi, '');
    baseName = baseName.replace(/剧场版/g, '');
    baseName = baseName.replace(/OVA|OAD|SP/gi, '');
    baseName = baseName.replace(/特别[篇编]/g, '');
    baseName = baseName.replace(/番外[篇编]?/g, '');
    baseName = baseName.replace(/之.+/g, '');
    baseName = baseName.replace(/\s+/g, '').trim();
    var searchKeys = [cleanName];
    if (baseName && baseName !== cleanName) searchKeys.push(baseName);
    var seasonInfo = extractSeasonInfo(cleanName);
    return { searchKeys: searchKeys, baseName: baseName, cleanName: cleanName, seasonInfo: seasonInfo };
}

