    if (!officialEpCount || officialEpCount <= 0) return results;
    var filtered = [];
    for (var i = 0; i < results.length; i++) {
        var r = results[i];
        if (r.type === 'official' || r.type === 'pan' || r.type === 'pan_sub') {
            filtered.push(r);
            continue;
        }
        if (r.epCount > officialEpCount * 2) {
            log('集数过滤: 剔除 ' + (r.name || r.playFrom || r.key) + ' epCount=' + r.epCount + ' > 官方' + officialEpCount + '*2');
