        for (var ci = 0; ci < searchRules.length; ci++) {
            var rule = searchRules[ci];
            var customResults = null;
            for (var si = 0; si < searchKeys.length; si++) {
                try {
                    var sr = cr.executeSearch(rule, searchKeys[si]);
                    if (sr && sr.length > 0) { customResults = sr; break; }
                } catch(e) { log("搜索规则[" + rule.name + "]关键词[" + searchKeys[si] + "]失败: " + e.message); }
            }
            if (!customResults || customResults.length === 0) continue;
            try {
                var hasPanUrl = false;
                for (var hp = 0; hp < customResults.length; hp++) {
                    if (getPanType(customResults[hp].url || '')) { hasPanUrl = true; break; }
                }
                if (hasPanUrl) {
                    var panTypeGroups = {};
                    var matchedPanItems = [];
                    for (var cj = 0; cj < customResults.length; cj++) {
                        var cr2 = customResults[cj];
