                    var ptKeys = Object.keys(panTypeGroups);
                    for (var ptk = 0; ptk < ptKeys.length; ptk++) {
                        var ptUrls = panTypeGroups[ptKeys[ptk]];
                        if (ptUrls.length > 0) {
