        var len;
        while ((len = gis.read(buffer)) != -1) { baos.write(buffer, 0, len); }
        gis.close();
        bais.close();
        baos.close();
        return String(new java.lang.String(baos.toByteArray(), "UTF-8"));
    } catch (e) { return null; }
}
function getLayerCache(layer, cacheKey, ttl) {
