            if (allResults !== undefined && allResults !== null) {
                if (allResults.length === 1 && allResults[0].type !== 'official') {
                    var origLine = allResults[0];
                    var isPanSingleLine = origLine.type === 'pan' || origLine.type === 'pan_sub' || origLine.type === 'magnet' || origLine._isPan || origLine.panType;
                    if (isPanSingleLine) {
                        if (!origLine.ruleName) origLine.ruleName = origLine.name || '其他';
                        var adFreeType = origLine.type;
                        allResults.push({
                            name: '🔁克隆',
