                }
                results = aggMergeBocaiResults(allResults);
                try { aggCache.setMerged(results); } catch (e) {}
            } else {
                results = aggCache.getMerged();
                if (results && results.length > 0) isCacheHit = true;
                if (!results || results.length === 0) results = [];
            }
            results = filterAggResultsByTitle(results, obj.title);
            try { aggCache.setMerged(results); } catch (e) {}
        }

        var categories = aggBuildCategories(results);
        if (opts.extraCategories && opts.extraCategories.length) {
            categories = opts.extraCategories.concat(categories);
        }
        if (categories.length === 0) return null;

        renderHeader(obj, categories);

        var aggState = new SourceStateManager('agg_' + obj.id);
        var selectedCat = aggState.get('category', getItem('bc_agg_cat_' + obj.id, categories[0].name));
        var activeCat = null;
        for (var i = 0; i < categories.length; i++) {
            if (categories[i].name === selectedCat) { activeCat = categories[i]; break; }
        }
        if (!activeCat) activeCat = categories[0];

        var catLines = activeCat.results;
        var selectedLineKey = aggState.get('line', getItem('bc_agg_line_' + obj.id, (catLines[0] && catLines[0].key) || ''));
        var lineFound = false;
        for (var i = 0; i < catLines.length; i++) {
