                try { selList = String(getMyVar(configs.uid + ":sel", "")).split("\n").filter(function(x) { return x; }); } catch (e) {}
            }
            files.forEach(function(dirPath) {
                var name = String(dirPath.getName());
                var fpath = String(dirPath.toString());
                var id = fpath || itemId + iki++;
                if (dirPath.isDirectory()) {
                    wjj.push({
