                                { title: "复制路径", js: $.toString(choose, configs, false, id, "复制路径") },
                                { title: "重命名", js: $.toString(choose, configs, false, id, "重命名") },
                                { title: "文件详细", js: $.toString(choose, configs, false, id, "文件详细") }
                            ]
                        }
                    });
                } else if (configs.pattern === 0) {
                    var type = getExtension(name);
                    if (configs.fileType && !targetType.test(type)) return;
                    var pic_url = iconGetter(fpath, type);
                    var isSel = selList.indexOf(fpath) >= 0;
                    wj.push({
                        title: (configs.multiple && isSel ? "✓ " : "") + name,
                        url: configs.multiple ? $("#noLoading#").lazyRule(toggleSel, fpath, configs, id, name) : $(tips.replace("${name}", name).replace("${path}", fpath))[configs.onClickType](choose, configs, false, id),
                        pic_url: pic_url,
                        col_type: colType,
                        extra: {
                            cls: configs.uid + ".文件(夹) " + itemCls,
                            id: id, path: fpath, type: type,
                            longClick: [
                                { title: "复制路径", js: $.toString(choose, configs, false, id, "复制路径") },
                                { title: "编辑文件", js: $.toString(choose, configs, false, id, "编辑文件") },
                                { title: "重命名", js: $.toString(choose, configs, false, id, "重命名") },
                                { title: "分享文件", js: $.toString(choose, configs, false, id, "分享文件") },
                                { title: "文件详细", js: $.toString(choose, configs, false, id, "文件详细") },
                                { title: "外部打开", js: $.toString(choose, configs, false, id, "外部打开") },
                                { title: "删除文件", js: $.toString(choose, configs, false, id, "删除文件") }
                            ]
                        }
                    });
                }
            });
            var fa = wjj.length > 0, fb = wj.length > 0;
            java.lang.Thread.sleep(40);
            if (fa) addItemAfter(configs.uid + "#文件夹", wjj);
            if (fb) addItemAfter(configs.uid + "#文件", wj);
            java.lang.Thread.sleep(65);
            if (wjj.length > 10 || wj.length > 10 || wjj.length + wj.length > 10) {
                updateItem(configs.uid + "#Bottom", { title: "““””<small><font color='gray'>到底了哦</font></small>", col_type: "text_center_1" });
            } else if (!(fa || fb)) {
                updateItem(configs.uid + "#Bottom", { title: "““””<small><font color='gray'>什么都没有呢</font></small>", col_type: "text_center_1" });
