            initialPath: getPath("hiker://files/").slice(7),
            rootDirPath: getPath("hiker://files/").slice(7)
        }, MYPARAMS);
        configs.initialPath = configs.initialPath || configs.rootDirPath;

        var _fsCloseAt = getMyVar("xj_filesel_close", "");
        if (_fsCloseAt) clearMyVar("xj_filesel_close");
        if (configs.multiple && _fsCloseAt && Date.now() - parseInt(_fsCloseAt) < 30000) {
