        if (!file.exists() || !file.isDirectory()) {
            back(false);
            toast("root:不存在该文件夹[" + file.getName() + "]");
            return;
        }
        var count = Number(dirPath.getNameCount());
        var dirPathInit = Paths.get(configs.initialPath);
        var fileInit = dirPathInit.toFile();
        if (!fileInit.exists() || !fileInit.isDirectory()) {
            toast("init:不存在该文件夹[" + fileInit.getName() + "]");
            configs.initialPath = configs.rootDirPath;
        }
        var countInit = Number(dirPathInit.getNameCount());
        if (countInit < count) {
            back(false);
            toast("init:count<root:count");
            return;
        }
        var data = d || [];
        data.push({
            col_type: "blank_block",
            extra: { id: configs.uid + "#变量", count: countInit, currentPath: configs.initialPath }
        });

        data.push({
            title: "搜索",
            url: $.toString(function(configs) {
                input = input.trim();
                if (input) {
                    if (input.startsWith("/") || input.startsWith("hiker://files/")) {
                        var path = input.replace("hiker://files/", getPath("hiker://files/").slice(7));
                        if (!fileExist("file://" + path)) return "toast://该文件(夹)不存在";
                        var load = $.require("function").fileSelect.init().loadFile;
                        load(path, configs, false);
                        return "hiker://empty";
                    }
                    var isRegular = findItem(configs.uid + "#正则").extra.isRegular || false;
                    return $("hiker://empty#noRefresh##noRecordHistory##noHistory##fullTheme#").rule(function(configs, key, isRegular) {
                        configs.isRegular = isRegular;
                        $.require("function").fileSelect.search(configs, key);
                    }, configs, input, isRegular);
                }
            }, configs),
            desc: "请输入文件名或文件路径",
            col_type: "input",
            extra: { id: configs.uid + "#搜索框1", onChange: $.toString(function(uid) {
                if (getMyVar(uid + ":back", "") === "true") {
                    clearMyVar(uid + ":back");
                    back(false);
                }
            }, configs.uid), configs: configs }
        });

        if (configs.multiple) {
            var initSelCount = String(getMyVar(configs.uid + ":sel", "")).split("\n").filter(function(x) { return x; }).length;
            data.push({
                title: "反选",
                url: $("#noLoading#").lazyRule(function(configs) {
                    var v = findItem(configs.uid + "#变量").extra;
                    var path = v.currentPath;
                    var files;
                    try { files = new java.io.File(path).listFiles(); } catch (e) { files = null; }
                    if (files == null) return "toast://权限不足或获取失败";
                    var targetType = configs.fileType ? new RegExp("(" + configs.fileType + ")$") : null;
                    var key = configs.uid + ":sel";
                    var cur = String(getMyVar(key, "")).split("\n").filter(function(x) { return x; });
                    var curSet = {}, localSet = {};
                    for (var ci = 0; ci < cur.length; ci++) curSet[cur[ci]] = true;
                    for (var fi = 0; fi < files.length; fi++) {
                        var f = files[fi];
                        if (f.isDirectory()) continue;
                        var fname = String(f.getName());
                        var dot = fname.lastIndexOf(".");
                        var ext = dot === -1 ? "" : fname.substring(dot).toLowerCase();
                        if (targetType && !targetType.test(ext)) continue;
                        localSet[String(f.toString())] = true;
                    }
                    var newSel = [];
                    for (var ni = 0; ni < cur.length; ni++) {
                        if (!localSet[cur[ni]]) newSel.push(cur[ni]);
                    }
                    for (var fp in localSet) {
                        if (localSet.hasOwnProperty(fp) && !curSet[fp]) newSel.push(fp);
                    }
                    putMyVar(key, newSel.join("\n"));
                    updateItem(configs.uid + "#确认选择", { title: "确认选择(" + newSel.length + ")" });
                    var load = $.require("function").fileSelect.init().loadFile;
                    load(path, configs, true);
                    return "hiker://empty";
                }, configs),
                col_type: "text_2",
                extra: { id: configs.uid + "#反选" }
            });
            data.push({
                title: "确认选择(" + initSelCount + ")",
                url: $("#noLoading#").lazyRule(function(callback, uid) {
                    var sel = String(getMyVar(uid + ":sel", "")).split("\n").filter(function(x) { return x; });
                    if (sel.length === 0) return "toast://未选择任何文件";
                    var callbackFunc = new Function("PATH", "TYPE", "ID", "return " + callback);
                    $.hiker.input = sel;
                    var callbackResult = callbackFunc(sel, "", "");
                    if (callbackResult === true) { back(false); return "hiker://empty"; }
                    if (callbackResult === false) return "hiker://empty";
                    return callbackResult;
                }, configs.callback, configs.uid),
                col_type: "text_2",
                extra: { id: configs.uid + "#确认选择" }
            });
        }

        if (configs.pattern === 1) {
