                    var callbackResult = callbackFunc(path, cls);
                    if (callbackResult === true) { back(false); return "hiker://empty"; }
                    if (callbackResult === false) return "hiker://empty";
                    return callbackResult;
                }, configs.callback, configs.uid),
                col_type: "text_2"
            });
        }

        var rankMethods = ["系统", "大小", "名称", "时间"];
        var rankMethod = "系统", rankOrder = "P";
        for (var mi = 0; mi < rankMethods.length; mi++) {
            var mname = rankMethods[mi];
            var a = rankMethod === mname;
            var titlea = a ? "''" + mname + "''" : mname;
            var titleb = a ? (rankOrder === "P" ? "↓" : "↑") : "↕";
            data.push({
                title: titlea + titleb,
                col_type: "flex_button",
                url: $("#noLoading#").lazyRule(function(mname, configs) {
                    var uid = configs.uid;
                    var values = findItem(uid + "#排序变量");
                    var rankMethod = values.title, rankOrder = values.desc;
                    var id = uid + "#rank:" + mname;
                    if (rankMethod === mname) {
                        updateItem(id, { title: "''" + mname + "''" + (rankOrder !== "P" ? "↓" : "↑") });
                        updateItem(uid + "#排序变量", { desc: rankOrder !== "P" ? "P" : "I" });
                    } else {
                        updateItem(id, { title: "''" + mname + "''↓" });
                        updateItem(uid + "#rank:" + rankMethod, { title: rankMethod + "↕" });
                        updateItem(uid + "#排序变量", { title: mname, desc: "P" });
                    }
                    var load = $.require("function").fileSelect.init().loadFile;
                    var basePath = findItem(configs.uid + "#变量").extra.currentPath;
                    load(basePath, configs);
                    return "hiker://empty";
                }, mname, configs),
                extra: { id: configs.uid + "#rank:" + mname }
            });
        }
        data.push({ col_type: "line", desc: rankOrder, title: rankMethod, extra: { id: configs.uid + "#排序变量" } });

        var funcType = "flex_button";
        data.push({
            title: "🔍正则◎",
            col_type: funcType,
            url: $("#noLoading#").lazyRule(function(uid) {
                var v = !!findItem(uid + "#正则").extra.isRegular;
                updateItem({ title: "🔍正则" + ["●", "◎"][Number(v)], extra: { id: uid + "#正则", isRegular: !v } });
                return "hiker://empty";
            }, configs.uid),
            extra: { id: configs.uid + "#正则", isRegular: false }
        }, {
            title: "🧩" + colTypes[0],
            col_type: funcType,
            url: $(colTypes, 2, "选择-显示样式").select(function(configs) {
