            extra: { id: configs.uid + "#样式", colType: colTypes[0] }
        });

        data.push({ title: "🗂初始", col_type: funcType, url: $("#noLoading#").lazyRule(function(configs, firstInitialPath) {
            var load = $.require("function").fileSelect.init().loadFile;
            load(firstInitialPath, configs);
            return "hiker://empty";
        }, configs, configs.initialPath) });

        data.push({ col_type: "blank_block" });
        data.push({
            title: "🏠 ''" + dirPath.getFileName() + "'' >",
            col_type: "scroll_button",
            url: $("#noLoading#").lazyRule(function(configs, count) {
                var load = $.require("function").fileSelect.init().loadFile;
