                if (del.length > 0) deleteItem(del);
                load("" + configs.rootDirPath, configs, true);
                return "hiker://empty";
            }, configs, count),
            extra: { id: configs.uid + "#路径" + (count - 1) }
        });

        data.push({ col_type: "line_blank", extra: { id: configs.uid + "#文件夹" } });
        data.push({ col_type: "blank_block" });
        data.push({ col_type: "blank_block" });
        data.push({ col_type: "line_blank", extra: { id: configs.uid + "#文件" } });
        data.push({ col_type: "blank_block" });
        data.push({ col_type: "blank_block" });
        data.push({ col_type: "line_blank" });
        data.push({ col_type: "blank_block", url: "hiker://empty", extra: { id: configs.uid + "#Bottom", lineVisible: false } });

        setResult(data);
        try { Thread.sleep(50); load(configs); } catch (e) {}
    }

