var cacheManager = {
    danmuDir: 'hiker://files/rules/星集Media/',
    cacheDir: 'hiker://files/cache/',
    tmpDir: 'hiker://files/_cache/',
    _patternToRegex: function(pattern) {
        var escaped = String(pattern).replace(/[.+^${}()|[\]\\]/g, '\\$&');
        escaped = escaped.replace(/\*/g, '.*').replace(/\?/g, '.');
        return new RegExp('^' + escaped + '$');
    },
    _resolveDir: function(hikerDir) {
        try {
            var p = String(getPath(hikerDir) || '');
            if (p.indexOf('file://') === 0) p = p.slice(7);
            return p;
        } catch (e) { return ''; }
    },
    _cleanDir: function(hikerDir, pattern, maxAgeMs, now) {
        var count = 0, bytes = 0;
        try {
            var dir = new java.io.File(this._resolveDir(hikerDir));
            if (!dir.exists() || !dir.isDirectory()) return 0;
            var files = dir.listFiles();
            if (!files) return 0;
            var regex = this._patternToRegex(pattern);
            for (var i = 0; i < files.length; i++) {
                var f = files[i];
                if (f.isDirectory()) continue;
                if (!regex.test(String(f.getName()))) continue;
                try {
                    var lastMod = f.lastModified();
                    if ((now - lastMod) >= maxAgeMs) { bytes += f.length(); if (f.delete()) count++; }
                } catch (e) {}
            }
        } catch (e) {}
        return { count: count, bytes: bytes };
    },
    _countDir: function(hikerDir, pattern, target) {
        try {
            var dir = new java.io.File(this._resolveDir(hikerDir));
            if (!dir.exists() || !dir.isDirectory()) return;
            var files = dir.listFiles();
            if (!files) return;
            var regex = this._patternToRegex(pattern);
            for (var i = 0; i < files.length; i++) {
                var f = files[i];
                if (f.isDirectory()) continue;
                if (!regex.test(String(f.getName()))) continue;
                target.count++;
                try { target.size += f.length(); } catch (e) {}
            }
        } catch (e) {}
    },
    autoCleanIfExpired: function() {
        try {
            var lastClean = parseInt(getMyVar('xj_last_auto_clean', '0')) || 0;
            var now = Date.now();
            if (now - lastClean < 24 * 60 * 60 * 1000) return null;
            putMyVar('xj_last_auto_clean', String(now));
            var days = parseInt(getItem('xj_cache_max_days', '7'));
            if (isNaN(days) || days <= 0) return null;
            return this.cleanExpired(days);
        } catch (e) { return null; }
    },
    cleanExpired: function(maxAgeDays) {
        var result = { danmu: 0, layer: 0, tmp: 0, bytes: 0 };
        try {
            if (maxAgeDays === undefined || maxAgeDays === null) maxAgeDays = 7;
            maxAgeDays = parseInt(maxAgeDays);
            if (isNaN(maxAgeDays) || maxAgeDays < 0) maxAgeDays = 7;
            var maxAgeMs = maxAgeDays * 24 * 60 * 60 * 1000;
            var now = Date.now();
            var r1 = this._cleanDir(this.danmuDir, 'external_danmu_*.json', maxAgeMs, now);
            var r2 = this._cleanDir(this.cacheDir, 'xj_*.json', maxAgeMs, now);
            var r3 = this._cleanDir(this.tmpDir, 'xj_*', maxAgeMs, now);
            result.danmu = r1.count; result.layer = r2.count; result.tmp = r3.count;
            result.bytes = r1.bytes + r2.bytes + r3.bytes;
        } catch (e) {}
        return result;
    },
    cleanAll: function() {
        return this.cleanExpired(0);
    },
    getStats: function() {
        var stats = {
            danmu: { count: 0, size: 0 },
            layer: { count: 0, size: 0 },
            tmp: { count: 0, size: 0 },
            total: { count: 0, size: 0 }
        };
        try {
            this._countDir(this.danmuDir, 'external_danmu_*.json', stats.danmu);
            this._countDir(this.cacheDir, 'xj_*.json', stats.layer);
            this._countDir(this.tmpDir, 'xj_*', stats.tmp);
            stats.total.count = stats.danmu.count + stats.layer.count + stats.tmp.count;
            stats.total.size = stats.danmu.size + stats.layer.size + stats.tmp.size;
        } catch (e) {}
        return stats;
    },
    formatSize: function(bytes) {
        bytes = Number(bytes) || 0;
        if (bytes < 1024) return bytes + 'B';
        if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + 'KB';
        if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + 'MB';
        return (bytes / (1024 * 1024 * 1024)).toFixed(2) + 'GB';
    }
};

function xjTvboxJoinPath(base, rel) {
    if (!rel || typeof rel !== 'string') return rel;
    if (rel.indexOf('http') === 0 || rel.indexOf('file://') === 0 || rel.indexOf('/') === 0) return rel;
    if (rel.indexOf('./') !== 0 && rel.indexOf('../') !== 0) return rel;
    if (base.indexOf('file://') === 0) {
        var baseDir = base.substring(7, base.lastIndexOf('/'));
        var parts = baseDir.split('/');
        var relParts = rel.split('/');
        for (var i = 0; i < relParts.length; i++) {
            if (relParts[i] === '.') continue;
            else if (relParts[i] === '..') parts.pop();
            else parts.push(relParts[i]);
        }
        return 'file://' + parts.join('/');
    } else if (base.indexOf('http') === 0) {
        return joinUrl(base, rel);
    }
    return rel;
}

function xjFetchTvboxContent(path) {
    if (!path) return '';
    if (path.indexOf('http') === 0) {
        return fetch(path, { headers: { "User-Agent": "okhttp/4.12.0" }, timeout: 20000 }) || '';
    }
    if (path.indexOf('file://') === 0) {
        return readFile(path.substring(7)) || '';
    }
    return readFile(path) || '';
}

function xjParseTvboxConfig(content) {
    if (!content) return null;
    content = content.replace(/\/\*[\s\S]*?\*\//g, '').trim();
    var cfgObj;
    try {
        cfgObj = JSON.parse(content);
    } catch (e) {
        try {
            var module = { exports: {} };
            var exports = module.exports;
            eval(content);
            cfgObj = module.exports || {};
            if (typeof cfgObj === 'string') cfgObj = JSON.parse(cfgObj);
        } catch (e2) {
            return null;
        }
    }
    return cfgObj;
}

function xjResolveTvboxExt(configPath, ext) {
    var sExt = '';
    if (typeof ext === 'object') {
        sExt = JSON.stringify(ext);
    } else if (typeof ext === 'string') {
        if (ext.indexOf('./') === 0 || ext.indexOf('../') === 0) {
            var absExtPath = xjTvboxJoinPath(configPath, ext);
            if (/\.json(\?|$)/i.test(absExtPath)) {
                try { sExt = xjFetchTvboxContent(absExtPath) || absExtPath; } catch (e) { sExt = absExtPath; }
            } else {
                sExt = absExtPath;
            }
        } else {
            sExt = ext;
        }
    }
    return sExt;
}

function xjImportTvboxSites(configPath, configName, cfgObj, opts) {
    opts = opts || {};
    var clearOld = opts.clearOld !== false;
    var c = getXjBase();
    var spider = cfgObj.spider || '';
    var sites = cfgObj.sites || [];
    var absSpider = spider ? xjTvboxJoinPath(configPath, spider) : '';
    var oldConfigPath = c.tvbox_config || '';
    c.tvbox_config = configPath;
    var siteKeys = [];
    for (var sk2 = 0; sk2 < sites.length; sk2++) {
        if (sites[sk2].key) siteKeys.push(String(sites[sk2].key));
    }
    c.tvbox_site_keys = siteKeys;
    if (configName) c.tvbox_config_name = configName;
    if (absSpider) {
        if (!c.jar_settings) c.jar_settings = { spider: '' };
        c.jar_settings.spider = absSpider;
    }
    saveXjBase(c);
    var tvboxRecPath = "hiker://files/rules/星集Media/xj_tvbox.json";
    if (clearOld) {
        try {
            var crClear = $.require("customRule");
            var oldRules = crClear.getRuleList();
            var tvRec = {};
            try { tvRec = JSON.parse(readFile(tvboxRecPath) || '{}'); } catch (eTv) {}
            var recEntry = { marks: {}, states: {} };
            for (var ori = 0; ori < oldRules.length; ori++) {
                var orId = oldRules[ori].id || '';
                var orType = oldRules[ori]['类型'] || '';
                if (orType === '本地包' || orId.indexOf('catvod_') === 0 || orId.indexOf('jar_') === 0) {
                    var orKey = oldRules[ori].key || '';
                    if (orKey) {
                        var orName = String(oldRules[ori].name || '');
                        var orCt = detectContentType(orName) === 'video' ? '' : detectContentType(orName);
                        if (orCt) recEntry.marks[orKey] = orCt;
                        var st = {};
                        if (oldRules[ori].enabled === false) st.enabled = false;
                        if (oldRules[ori].searchEnabled === true) st.searchEnabled = true;
                        if (oldRules[ori].parseEnabled === true) st.parseEnabled = true;
                        if (oldRules[ori].aggEnabled === true) st.aggEnabled = true;
                        if (st.enabled === false || st.searchEnabled === true || st.parseEnabled === true || st.aggEnabled === true) recEntry.states[orKey] = st;
                    }
                    try { crClear.removeRuleKeepFile(oldRules[ori].id); } catch (e) {}
                }
            }
            if (oldConfigPath) {
                if (Object.keys(recEntry.marks).length > 0 || Object.keys(recEntry.states).length > 0) tvRec[oldConfigPath] = recEntry;
                else delete tvRec[oldConfigPath];
                saveFile(tvboxRecPath, JSON.stringify(tvRec));
            }
        } catch (eClear) {}
        try {
            var cfgClean = getXjBase();
            if (cfgClean.bocai_sites && cfgClean.bocai_sites.length > 0) {
                var oldKeys = {};
                if (oldConfigPath && oldConfigPath !== configPath) {
                    try {
                        var oldContent = xjFetchTvboxContent(oldConfigPath);
                        if (oldContent) {
                            var oldCfg = xjParseTvboxConfig(oldContent) || {};
                            var oldSites = oldCfg.sites || [];
                            for (var oki = 0; oki < oldSites.length; oki++) {
                                if (oldSites[oki].key) oldKeys[String(oldSites[oki].key)] = true;
                            }
                        }
                    } catch (eOld) {}
                }
                var keptSites = [];
                var removedBocai = 0;
                for (var ci = 0; ci < cfgClean.bocai_sites.length; ci++) {
                    var bs = cfgClean.bocai_sites[ci];
                    if (bs.fromTvbox || oldKeys[String(bs.key)]) { removedBocai++; continue; }
                    keptSites.push(bs);
                }
                if (removedBocai > 0) {
                    cfgClean.bocai_sites = keptSites;
                    saveXjBase(cfgClean);
                }
            }
        } catch (eCleanBocai) {}
    }
    var jarRules = [];
    var bocaiRules = [];
    var skipCount = 0;
    for (var i = 0; i < sites.length; i++) {
        var s = sites[i];
        if (!s.key || !s.name) { skipCount++; continue; }
        var sType = s.type !== undefined ? s.type : 3;
        var sApi = String(s.api || '');
        var isCspSource = sApi.indexOf('csp_') === 0;
        var isXmlSource = (sType === 0 || sType === 1 || sType === 4) && /^https?:\/\//i.test(sApi);
        if (sType === 0 && !isCspSource && !/^https?:\/\//i.test(sApi)) { skipCount++; continue; }
        if (!isCspSource && !isXmlSource) { skipCount++; continue; }
        var sEnabled = s.enabled !== false;
        if (isXmlSource) {
            bocaiRules.push({
                key: s.key,
                name: s.name,
                api: sApi,
                detail: s.detail || '',
                enabled: sEnabled
            });
        } else {
            var sJar = s.jar ? xjTvboxJoinPath(configPath, s.jar) : absSpider;
            jarRules.push({
                name: s.name + ' [本地包]',
                key: s.key,
                api: sApi,
                jar: sJar,
                ext: xjResolveTvboxExt(configPath, s.ext),
                enabled: sEnabled
            });
        }
    }
    var imported = 0;
    try {
        var cr = $.require("customRule");
        for (var ji = 0; ji < jarRules.length; ji++) {
            var jr = jarRules[ji];
            var ruleData = {
                name: jr.name,
                '类型': '本地包',
                host: jr.jar || '',
                api: jr.api,
                jar: jr.jar || '',
                ext: jr.ext || '',
                enabled: jr.enabled !== false
            };
            if (jr.key) {
                ruleData.key = jr.key;
                ruleData.id = 'jar_' + jr.key;
            }
            cr.saveRule(ruleData);
            imported++;
        }
    } catch (eImp) {
        log('xjImportTvboxSites: jar导入失败: ' + eImp.message);
    }
    var bocaiImported = 0;
    if (bocaiRules.length > 0) {
        try {
            var cfgBocai = getXjBase();
            if (!cfgBocai.bocai_sites) cfgBocai.bocai_sites = [];
            var existKeys = {};
            for (var ek = 0; ek < cfgBocai.bocai_sites.length; ek++) {
                existKeys[cfgBocai.bocai_sites[ek].key] = true;
            }
            var maxEnabled = parseInt(getItem('xj_bocai_max_enabled', '5'));
            if (isNaN(maxEnabled) || maxEnabled < 1) maxEnabled = 5;
            var existEnabledCount = 0;
            for (var ek2 = 0; ek2 < cfgBocai.bocai_sites.length; ek2++) {
                if (cfgBocai.bocai_sites[ek2].enabled !== false) existEnabledCount++;
            }
            for (var bi = 0; bi < bocaiRules.length; bi++) {
                var br = bocaiRules[bi];
                if (existKeys[br.key]) continue;
                var newEnabled = existEnabledCount < maxEnabled;
                cfgBocai.bocai_sites.push({
                    key: br.key,
                    name: br.name,
                    api: br.api,
                    detail: br.detail,
                    enabled: newEnabled,
                    fromTvbox: true
                });
                existKeys[br.key] = true;
                if (newEnabled) existEnabledCount++;
                bocaiImported++;
            }
            saveXjBase(cfgBocai);
        } catch (eBocai) {
            log('xjImportTvboxSites: 采集源导入失败: ' + eBocai.message);
        }
    }
    var parseImported = 0;
    try {
        var tvParses = cfgObj.parses || [];
        for (var pi = 0; pi < tvParses.length; pi++) {
            var tp = tvParses[pi];
            if (!tp || !tp.url) continue;
            var tpName = String(tp.name || '').trim();
            var tpUrl = String(tp.url).trim();
            if (!tpUrl || !/^https?:\/\//i.test(tpUrl)) continue;
            var tpType = parseInt(tp.type);
            var qdType = null;
            if (tpType === 0) qdType = 'X';
            else if (tpType === 1) qdType = 'Z';
            else continue;
            var cfgP = getXjBase();
            if (!cfgP.parses) cfgP.parses = [];
            var existsP = -1;
            for (var pj = 0; pj < cfgP.parses.length; pj++) {
                if (cfgP.parses[pj].name === tpName && cfgP.parses[pj].url === tpUrl) { existsP = pj; break; }
            }
            var pItem = { name: tpName || ('解析' + (pi + 1)), type: qdType, url: tpUrl, enabled: true };
            if (existsP >= 0) {
                pItem.enabled = cfgP.parses[existsP].enabled === false ? false : true;
                cfgP.parses[existsP] = pItem;
            } else {
                cfgP.parses.push(pItem);
                parseImported++;
            }
            saveXjBase(cfgP);
        }
    } catch (eParse) {
        log('xjImportTvboxSites: 解析导入失败: ' + eParse.message);
    }
    if (clearOld) {
        try {
            var cr2 = $.require("customRule");
            var tvRec2 = {};
            try { tvRec2 = JSON.parse(readFile(tvboxRecPath) || '{}'); } catch (eTv2) {}
            var recNew = tvRec2[configPath] || {};
            var recMarks = recNew.marks || {};
            var recStates = recNew.states || {};
            if (Object.keys(recMarks).length > 0 || Object.keys(recStates).length > 0) {
                var newRules2 = cr2.getRuleList();
                for (var nri = 0; nri < newRules2.length; nri++) {
                    var nr = newRules2[nri];
                    var nrKey = nr.key || '';
                    if (((nr['类型'] || '') === '本地包' || (nr.id || '').indexOf('jar_') === 0) && nrKey && (recMarks[nrKey] || recStates[nrKey])) {
                        var nrChanged = false;
                        if (recMarks[nrKey]) {
                            var nrNm = String(nr.name || '').replace(/\s*\[(画|音|书)\]\s*/g, '').replace(/\s*\[本地包\]\s*/g, '').trim();
                            if (recMarks[nrKey] === 'comic') nrNm += ' [画]';
                            else if (recMarks[nrKey] === 'book') nrNm += ' [书]';
                            else nrNm += ' [音]';
                            nrNm += ' [本地包]';
                            nr.name = nrNm;
                            nrChanged = true;
                        }
                        var sst = recStates[nrKey];
                        if (sst) {
                            if (sst.enabled === false && nr.enabled !== false) { nr.enabled = false; nrChanged = true; }
                            if (sst.searchEnabled === true && nr.searchEnabled !== true) { nr.searchEnabled = true; nrChanged = true; }
                            if (sst.parseEnabled === true && nr.parseEnabled !== true) { nr.parseEnabled = true; nrChanged = true; }
                            if (sst.aggEnabled === true && nr.aggEnabled !== true) { nr.aggEnabled = true; nrChanged = true; }
                        }
                        if (nrChanged) { cr2.saveRule(nr); }
                    }
                }
            }
        } catch (eRestore) {}
    }
    return {
        jarCount: imported,
        bocaiCount: bocaiImported,
        parseCount: parseImported,
        skipCount: skipCount,
        total: sites.length
    };
}

function disableLocalPackage() {
    var cr = $.require("customRule");
    var cleared = { rules: 0, jarCleared: false, dexFiles: 0, stateCleared: false };
    try {
        var allRules = cr.getRuleList();
        var localIds = [];
        for (var i = 0; i < allRules.length; i++) {
            var rType = allRules[i]['类型'] || '';
            var rId = allRules[i].id || '';
            if (rType === '本地包' || rId.indexOf('catvod_') === 0 || rId.indexOf('jar_') === 0) localIds.push(allRules[i].id);
        }
        for (var j = 0; j < localIds.length; j++) {
            try { cr.removeRuleKeepFile(localIds[j]); cleared.rules++; } catch (e) {}
        }
    } catch (e) {}
    try { cleared.jarCleared = cr.clearJarSpiders(); } catch (e2) {}
    try {
        var cfgDis = getXjBase();
        if (cfgDis.bocai_sites && cfgDis.bocai_sites.length > 0) {
            var tvKeys = {};
            var tvPath = cfgDis.tvbox_config || '';
            if (tvPath) {
                try {
                    var tvContent = xjFetchTvboxContent(tvPath);
                    if (tvContent) {
                        var tvCfg = xjParseTvboxConfig(tvContent) || {};
                        var tvSites = tvCfg.sites || [];
                        for (var ti = 0; ti < tvSites.length; ti++) {
                            if (tvSites[ti].key) tvKeys[String(tvSites[ti].key)] = true;
                        }
                    }
                } catch (eTv) {}
            }
            var kept = [];
            for (var di = 0; di < cfgDis.bocai_sites.length; di++) {
                var ds = cfgDis.bocai_sites[di];
                if (ds.fromTvbox || tvKeys[String(ds.key)]) continue;
                kept.push(ds);
            }
            cfgDis.bocai_sites = kept;
        }
        delete cfgDis.tvbox_config;
        delete cfgDis.tvbox_config_name;
        delete cfgDis.tvbox_site_keys;
        if (cfgDis.jar_settings) { delete cfgDis.jar_settings.spider; }
        saveXjBase(cfgDis);
    } catch (eDis) {}
    try {
        var FileCls = java.io.File;
        var jarDir = new FileCls(getPath('hiker://files/cache/星集Media/jar/'));
        if (jarDir.exists() && jarDir.isDirectory()) {
            var files = jarDir.listFiles();
            if (files) {
                for (var k = 0; k < files.length; k++) {
                    try { if (files[k].delete()) cleared.dexFiles++; } catch (e3) {}
                }
            }
        }
    } catch (e4) {}
    try {
        var jarStatesPath = "hiker://files/rules/星集Media/xj_jar_rule_states.json";
        if (fileExist(jarStatesPath)) { deleteFile(jarStatesPath); cleared.stateCleared = true; }
    } catch (e5) {}
    try { setItem('xj_local_pkg_disabled', '1'); } catch (e6) {}
    return cleared;
}

