function sortSx(arr, name, style, order) {
    if (style == 1) {
        arr.sort((a, b) => {
            var va = String(a[name] || "");
            var vb = String(b[name] || "");
            return va.localeCompare(vb);
        });
    } else if (style == 2) {
        arr.sort((a, b) => {
            var va = String(a[name] || "");
            var vb = String(b[name] || "");
            return va.localeCompare(vb);
        });
        var m = arr.findIndex(it => /^[\u4e00-\u9fa5]/.test(String(it[name] || "")));
        var n = arr.findLastIndex(it => /^[\u4e00-\u9fa5]/.test(String(it[name] || "")));
        if (m > -1) { var tmp = arr.splice(m, n - m + 1); arr = arr.concat(tmp); }
    } else if (style == 3) {
        arr.sort((a, b) => {
            var na = parseInt((String(a[name] || "").match(/\d+/) || [99999999999999])[0]);
