        if (input.includes("pwd=")) {
            if (input.includes("/s/")) {
                path1 = input.match(/([\w_-]{23}).+pwd=(\w+)/);
                if (path1) return path1[1] + "?pwd=" + path1[2];
            } else if (input.includes("surl=")) {
