var javaString = java.lang.String;
var Base64 = java.util.Base64;
var GZIPOutputStream = java.util.zip.GZIPOutputStream;
var GZIPInputStream = java.util.zip.GZIPInputStream;
var ByteArrayOutputStream = java.io.ByteArrayOutputStream;
var ByteArrayInputStream = java.io.ByteArrayInputStream;

function zip(text) {
    var baseStr = new javaString(text);
    var baos = new ByteArrayOutputStream();
    var gzos = new GZIPOutputStream(baos);
    gzos.write(baseStr.getBytes("UTF-8"));
    gzos.close();
    var compressedData = baos.toByteArray();
    var base64String = Base64.getEncoder().encodeToString(compressedData);
    baos.close();
    return String(base64String);
}

function unzip(text) {
    var compressedData = Base64.getDecoder().decode(text);
    var bais = new ByteArrayInputStream(compressedData);
    var baos = new ByteArrayOutputStream();
    var buffer = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
    var gis = new GZIPInputStream(bais);
    var len;
    while ((len = gis.read(buffer)) != -1) {
        baos.write(buffer, 0, len);
    }
    gis.close();
    bais.close();
    baos.close();
    var decompressedString = new javaString(baos.toByteArray(), "UTF-8");
    return String(decompressedString);
}

$.exports = { zip: zip, unzip: unzip };"},{"col_type":"text_1","name":"hikerPop.js","path":"hikerPop.js","rule":"// author@LoyDgIk
