function getBookList(arr) {
    let list = new ArrayList();
    for (let it of arr) {
        let bookmark = new Bookmark();
        bookmark.setTitle(it.title || "");
        bookmark.setDir(false);
        bookmark.setUrl(it.url || it.title || "");
        bookmark.setIcon(it.icon || "");
        list.add(bookmark);
    }
    return list;
}

