function findRecyclerView(viewGroup) {
    for (let i = 0; i < viewGroup.getChildCount(); i++) {
        let child = viewGroup.getChildAt(i);
        let name = child.getClass().getSimpleName();

        if (name == "RecyclerView") {
            return child;
        }
