        beforeShow(basePopupView) {
            scrollToPosition(toPosition);
            tryCallBack(getDefaultValue(beforeShow, "function", null), [pop, resOptionsManage]);
        }
    }));
    pop = pop.moveUpToKeyboard(false).asCustom(custom);
    showOnUI(pop);
    return pop;
}

