var r = JSON.parse(resp);<br>
var body = r.body;<br>
var headers = r.headers;  // 每个key对应array<br>
<br>
var resp = this.fetchHtml(url, { onlyHeaders: true });<br>
<br>
var resp = this.fetchHtml(url, { withStatusCode: true });<br>
var r = JSON.parse(resp);<br>
var statusCode = r.statusCode;</font></small></p>

