<p style="background:#f5f5f5;padding:8px;border-radius:4px;"><small><font face="monospace">if (playerObj.encrypt == '1') vUrl = unescape(vUrl);<br>
else if (playerObj.encrypt == '2') vUrl = unescape(base64Decode(vUrl));</font></small></p>

