function fetchCategories(sourceKey) {

    var homeRule = isHomeRule(sourceKey);

    if (homeRule) {

        var cats = cr.getCategories(homeRule);

        return { tree: cats, hasPid: false };

    }

    var site = getApiSites()[sourceKey];

    if (!site) return { tree: [], hasPid: false };

    var cacheKey = 'bocai_cats_v2_' + sourceKey;

    var cached = getMyVar(cacheKey, '');

    if (cached) {

        try {

            var data = JSON.parse(cached);

            if (data.ts && (Date.now() - data.ts < 12 * 60 * 60 * 1000)) {

                var filterNames = { '资讯': 1, '资讯片': 1 };

                var filteredTree = [];

                for (var i = 0; i < data.tree.length; i++) {

                    if (filterNames[data.tree[i].name]) continue;

                    filteredTree.push(data.tree[i]);

                }

                return { tree: filteredTree, hasPid: data.hasPid };

            }

        } catch (e) {}

    }

    var result = { tree: [], hasPid: false };

    try {

        var resp = fetch(site.api + '?ac=list&pg=1&pagesize=1', {

            timeout: 8000,

            headers: { 'User-Agent': 'Mozilla/5.0' }

        });

        if (!resp || !resp.trim() || resp.trim().charAt(0) === '<') {

            putMyVar(cacheKey, JSON.stringify({ ts: Date.now(), tree: result.tree, hasPid: result.hasPid }));

            return result;

        }

        var json = JSON.parse(resp);

        if (json && json.class && json.class.length > 0) {

            var classList = json.class;

            var hasPid = false;

            for (var i = 0; i < classList.length; i++) {

                if (typeof classList[i].type_pid !== 'undefined') { hasPid = true; break; }

            }

            if (hasPid) {

                result.hasPid = true;

                var parents = {};

                var children = {};

                var filterNames = { '资讯': 1, '资讯片': 1 };

                for (var i = 0; i < classList.length; i++) {

                    var item = classList[i];

                    if (filterNames[item.type_name]) continue;

                    if (item.type_pid && item.type_pid > 0) {

                        if (!children[item.type_pid]) children[item.type_pid] = [];

                        children[item.type_pid].push({ id: item.type_id, name: item.type_name });

                    } else {

                        parents[item.type_id] = { id: item.type_id, name: item.type_name, children: [] };

                    }

                }

                for (var pid in children) {

                    if (parents[pid]) { parents[pid].children = children[pid]; }

                    else { parents[pid] = { id: parseInt(pid), name: '分类' + pid, children: children[pid] }; }

                }

                for (var pid in parents) result.tree.push(parents[pid]);

                result.tree.sort(function(a, b) { return a.id - b.id; });

                for (var i = 0; i < result.tree.length; i++) {

                    result.tree[i].children.sort(function(a, b) { return a.id - b.id; });

                }

            } else {

                var parentNames = { '电影片': 1, '连续剧': 1, '综艺片': 1, '动漫片': 1, '电影': 1, '电视剧': 1, '综艺': 1, '动漫': 1 };

                var filterNames = { '资讯': 1, '资讯片': 1 };

                for (var i = 0; i < classList.length; i++) {

                    var item = classList[i];

                    if (filterNames[item.type_name]) continue;

                    if (!parentNames[item.type_name]) {

                        result.tree.push({ id: item.type_id, name: item.type_name, children: [] });

                    }

                }

                if (result.tree.length === 0) {

                    for (var i = 0; i < classList.length; i++) {

                        result.tree.push({ id: classList[i].type_id, name: classList[i].type_name, children: [] });

                    }

                }

                result.tree.sort(function(a, b) { return a.id - b.id; });

            }

        }

    } catch (e) {}

    putMyVar(cacheKey, JSON.stringify({ ts: Date.now(), tree: result.tree, hasPid: result.hasPid }));

    return result;

}



