                        });
                    } catch (e) {}
                })(aepNum, dEpName, dFrozenUrls, dFrozenNames, dFrozenRIds, dFrozenFlags, obj.id);
            }
        }
    }

    try { putMyVar('tmdb_ep_match_bc_' + obj.id, JSON.stringify(epMatchStore)); } catch(eMs) {}

    if (needAiEps.length > 0 && sparkKey && !getMyVar('tmdb_ai_running', '')) {
