            try {
                var matchObj = JSON.parse(jsonMatch[0]);
                if (matchObj.matches) {
                    for (var mi = 0; mi < matchObj.matches.length; mi++) {
                        var m = matchObj.matches[mi];
                        if (m.tmdb_ep && m.bindings) aiMatches[m.tmdb_ep] = m.bindings;
