                                                        }
                                                    }
                                                }
                                            } catch (eLz) {}
                                        }
                                        if (typeof resolvedUrl === 'string' && resolvedUrl.indexOf('pan://') === 0) {
                                            return fn.resolvePanJump(resolvedUrl);
                                        }
                                        if (typeof resolvedUrl === 'string' && resolvedUrl.indexOf('{"urls"') === 0) {
                                            try {
                                                var pj = JSON.parse(resolvedUrl);
