                                    if (vUrls.length === 0) return 'toast://链接解析失败,该源解析无结果';
                                    var result = { urls: vUrls, names: sNames2 };
                                    var hasHdr = false;
                                    for (var hi = 0; hi < vHeaders.length; hi++) { if (vHeaders[hi] && vHeaders[hi]['User-Agent']) { hasHdr = true; break; } }
