function renderAggResults(obj, allResults) {
    if (hasSynopsis) {
        var synLine = {
            name: 'TMDB', key: 'tmdb_synopsis', type: 'tmdb_synopsis', playFrom: '聚合选集',
            epCount: synopsisEpisodes.length,
            playUrl: synopsisEpisodes.map(function(ep) {
                var epTitle = ep.name || '';
                var hasEpNum = epTitle.match(/第\s*\d+\s*[期集]/) || epTitle.match(/第\s*[一二三四五六七八九十百千]+\s*[期集]/) || epTitle.match(/^\d+$/);
                if (!epTitle) epTitle = '第' + ep.episode_number + '集';
                else if (!hasEpNum) epTitle = '第' + ep.episode_number + '集 ' + epTitle;
                return epTitle + '$synopsis_' + ep.episode_number;
            }).join('#'),
            _synopsisEps: synopsisEpisodes.map(function(ep) {
                return {
                    episode_number: ep.episode_number,
                    name: ep.name || '',
                    air_date: ep.air_date || '',
                    overview: ep.overview || '',
                    still: ep.still_path ? (TMDB_IMG_BASE + '/w400' + ep.still_path) : ''
                };
            })
        };
        if (allResults && allResults.length > 0) {
            allResults = [synLine].concat(allResults);
        } else {
            var mc = fn.AggCacheManager(obj.id).getMerged();
            if (mc && mc.length > 0) {
                var mcHasSyn = false;
                for (var mci = 0; mci < mc.length; mci++) { if (mc[mci] && mc[mci].type === 'tmdb_synopsis') { mcHasSyn = true; break; } }
                if (!mcHasSyn) fn.AggCacheManager(obj.id).setMerged([synLine].concat(mc));
            } else {
                allResults = [synLine];
            }
        }
    }
    var renderer = fn.createAggRenderer({});
    var state = renderer.render(obj, allResults);
    if (allResults && allResults.length > 0) doAutoMatch(obj, allResults);
    return state;
}

