function buildVideoExtra(baseExtra) {
    var extra = baseExtra || {};
    extra.blockRules = ['.jpg', '.png', '.gif', '.webp', '.jpeg', '.bmp', '.svg', '.ico', '.css', '.woff', '.ttf'];
    extra.cacheM3u8 = true;
    return extra;
}

function buildCategories(results) {
    var officialGroup = [];
    var ruleGroups = {};
    var bocaiGroup = [];
    for (var i = 0; i < results.length; i++) {
        var r = results[i];
        if (r.type === 'official') officialGroup.push(r);
        else if (r.type === 'bocai') bocaiGroup.push(r);
        else {
            var gName = r.ruleName || r.name || '其他';
            gName = gName.replace(/^[🎬🔍]/, '').trim();
            if (!ruleGroups[gName]) ruleGroups[gName] = [];
            ruleGroups[gName].push(r);
        }
    }

    var categories = [];
    if (officialGroup.length > 0) categories.push({ name: '官方源', results: officialGroup });
    var gKeys = Object.keys(ruleGroups);
    for (var gi = 0; gi < gKeys.length; gi++) {
        categories.push({ name: gKeys[gi], results: ruleGroups[gKeys[gi]] });
    }
    if (bocaiGroup.length > 0) categories.push({ name: '菠菜源', results: bocaiGroup });
    return categories;
}

function renderHeader(obj, categories) {
    deleteItem('bocai_agg_header');
    deleteItemByCls('agg_cat_btn');
    if (!categories || categories.length === 0) return;

    var aggState = fn.SourceStateManager ? fn.SourceStateManager('agg_' + obj.id) : null;
    var selectedCat = aggState ? aggState.get('category', getItem('bc_agg_cat_' + obj.id, categories[0].name)) : getItem('bc_agg_cat_' + obj.id, categories[0].name);
    var catFound = false;
    for (var i = 0; i < categories.length; i++) {
        if (categories[i].name === selectedCat) { catFound = true; break; }
    }
    if (!catFound) selectedCat = categories[0].name;

    var headerItems = [];
    headerItems.push({
        title: '\u2018\u2018\u2019\u2019<big>🎍 聚合源</big> 请勿相信剧中任何广告!!!',
        url: 'hiker://empty',
        col_type: 'text_center_1',
        extra: {
            lineVisible: false,
            id: 'bocai_agg_header'
        }
    });

    var catColorMap = { '官方源': '#339AF0', '菠菜源': '#FF6B6B' };
    var catColors = ['#FFA94D', '#845EF7', '#51CF66', '#20C997', '#339AF0', '#F06595', '#FCC419'];
    for (var i = 0; i < categories.length; i++) {
        var cat = categories[i];
        var isSelected = (cat.name === selectedCat);
        var maxEpCount = 0;
        for (var j = 0; j < cat.results.length; j++) {
            if (cat.results[j].epCount > maxEpCount) maxEpCount = cat.results[j].epCount;
        }
        var isPanCat = cat.results[0] && cat.results[0].type === 'pan';
        var unitLabel = isPanCat ? '条' : '集';
        var label = cat.name + '(' + maxEpCount + unitLabel + ')';
        var catColor = catColorMap[cat.name] || catColors[i % catColors.length] || (isPanCat ? '#845EF7' : '#51CF66');
        headerItems.push({
            title: isSelected ? '\u2018\u2018\u2019\u2019<b><font color="' + catColor + '">' + label + '</font></b>' : '\u2018\u2018\u2019\u2019' + label,
            col_type: 'scroll_button',
            url: $('#noLoading#').lazyRule(function(id, c) {
                var st = $.require('function').SourceStateManager('agg_' + id);
                var limit = $.require('function').getPageSize();
                st.merge({category: c, line: '', page: 0, limit: limit});
                setItem('bc_agg_cat_' + id, c);
                setItem('bc_agg_line_' + id, '');
                setItem('bc_agg_page_' + id, '0');
                setItem('bc_agg_limit_' + id, String(limit));
                refreshPage(false);
                return 'hiker://empty';
            }, obj.id, cat.name),
            extra: { cls: 'agg_cat_btn' }
        });
    }
    addItemBefore('bocai_agg', headerItems);
}

