                        return;
                    }
                    aggCache.setResults(officialResults);
                    renderAggResults(obj, officialResults);
                    return;
                }

                var totalCount = tasks.length + ruleTasks.length;
                var loadedCount = new java.util.concurrent.atomic.AtomicInteger(0);
                var completedCount = new java.util.concurrent.atomic.AtomicInteger(0);
                var merged = new java.util.concurrent.atomic.AtomicBoolean(false);
                var cancelled = new java.util.concurrent.atomic.AtomicBoolean(false);
                _mvAggThreads = [];
                var allThreads = _mvAggThreads;
                var allDynamicResults = { official: officialResults, rules: {}, bocai: [], verify: [] };
                var GLOBAL_TIMEOUT = 15000;

                renderHeader(obj, buildCategories(officialResults));
                addItemBefore('bocai_agg', {
                    title: '\u2018\u2018\u2019\u2019<font color="#4FC3F7">\u23f3 正在搜索播放源(0/' + totalCount + '已加载)...</font>',
                    col_type: 'text_center_1',
                    extra: { id: 'bocai_loading', lineVisible: false }
                });

                if (officialResults.length > 0) {
                    loadedCount.incrementAndGet();
                    updateItem('bocai_loading', {
                        title: '\u2018\u2018\u2019\u2019<font color="#4FC3F7">\u23f3 正在搜索播放源(' + loadedCount.get() + '/' + totalCount + '已加载)...</font>'
                    });
                    renderAggResults(obj, officialResults);
                }

                function doMerge() {
                    if (!merged.compareAndSet(false, true)) return;
                    cancelled.set(true);
                    try { safetyTimer.cancel(); } catch(e){}
                    for (var ti2 = 0; ti2 < allThreads.length; ti2++) {
                        try { allThreads[ti2].interrupt(); } catch(e){}
                    }
                    try {
                        var act = getCurrentActivity();
                        if (!act || act.isFinishing() || act.isDestroyed()) return;
                    } catch(e) { return; }
                    if (getMyVar('xj_agg_active_page', '') !== obj.id) return;
                    try { deleteItem('bocai_loading'); } catch(e){}
                    try { deleteItem('bocai_agg_loading'); } catch(e){}

                    var finalResults = allDynamicResults.official.slice();
                    for (var rn in allDynamicResults.rules) {
                        finalResults = finalResults.concat(allDynamicResults.rules[rn]);
                    }
                    finalResults = finalResults.concat(allDynamicResults.bocai);
                    log('[doMerge] official=' + allDynamicResults.official.length + ' rules=' + JSON.stringify(Object.keys(allDynamicResults.rules).map(function(k){return k+':'+allDynamicResults.rules[k].length})) + ' bocai=' + allDynamicResults.bocai.length + ' total=' + finalResults.length);
                    aggCache.setResults(finalResults);

                    if (finalResults.length > 0) {
                        renderAggResults(obj, finalResults);
                    } else if (allDynamicResults.verify.length > 0) {
                        addItemBefore('bocai_agg', { title: '\u2018\u2018\u2019\u2019<font color="#FFB74D">部分规则源需要人机验证，请完成验证后下拉刷新</font>', url: 'hiker://page/parse#noHistory##noRecordHistory##noPre#', col_type: 'text_center_1' });
                    } else {
                        addItemBefore('bocai_agg', { title: '\u2018\u2018\u2019\u2019<font color="#999999">未找到匹配的播放源</font>', url: 'hiker://empty', col_type: 'text_center_1' });
                    }
                }

                function onSourceComplete(type, result) {
                    if (cancelled.get()) return;
                    if (result && result.length > 0) {
                        if (type === 'bocai') {
                            for (var i = 0; i < result.length; i++) allDynamicResults.bocai.push(result[i]);
                        } else {
                            for (var i = 0; i < result.length; i++) {
                                if (result[i] && result[i]._needVerify) {
                                    allDynamicResults.verify.push(result[i]);
                                    continue;
                                }
                                var rn = result[i].ruleName || result[i].name || '其他';
                                rn = rn.replace(/^[🎬🔍🌿]/, '').trim();
                                if (!allDynamicResults.rules[rn]) allDynamicResults.rules[rn] = [];
                                allDynamicResults.rules[rn].push(result[i]);
                            }
                        }
                    }
                    var curLoaded = loadedCount.incrementAndGet();
                    try {
                        updateItem('bocai_loading', {
                            title: '\u2018\u2018\u2019\u2019<font color="#4FC3F7">\u23f3 正在搜索播放源(' + curLoaded + '/' + totalCount + '已加载)...</font>'
                        });
                    } catch(e){}
                }

                function onAllComplete() {
                    if (completedCount.incrementAndGet() >= totalCount) {
                        doMerge();
                    }
                }

                _mvAggTimer = new java.util.Timer();
                var safetyTimer = _mvAggTimer;
                safetyTimer.schedule(new java.util.TimerTask({
                    run: function() {
                        log('【聚合源】触发全局安全超时');
                        try { safetyTimer.cancel(); } catch(e){}
                        doMerge();
                    }
                }), GLOBAL_TIMEOUT);

                function runTaskThread(task) {
                    var t = new java.lang.Thread(new java.lang.Runnable({
                        run: function() {
                            if (cancelled.get()) { onAllComplete(); return; }
                            var taskStart = Date.now();
                            var result = [];
                            try {
                                result = task.func(task.param) || [];
                            } catch (e) {
                                try { if (java.lang.Thread.currentThread().isInterrupted()) return; } catch(eI) {}
                                log('【源异常】' + task.id + ': ' + e.message);
                            }
                            log('【源耗时】' + task.id + ' | ' + (Date.now() - taskStart) + 'ms');
                            var srcType = (task.id.indexOf('rule_') === 0) ? 'rule' : 'bocai';
                            onSourceComplete(srcType, result);
                            onAllComplete();
                        }
                    }));
                    allThreads.push(t);
                    t.start();
                }
                for (var ti = 0; ti < tasks.length; ti++) {
                    runTaskThread(tasks[ti]);
                }
                for (var rti = 0; rti < ruleTasks.length; rti++) {
                    runTaskThread(ruleTasks[rti]);
                }

            } catch (e) {
                log('聚合搜索失败: ' + e.message);
            }
        },
        param: { id: MY_PARAMS.id, title: json.title, target_type: MY_PARAMS.target_type }
    }]);
    }
}

