            if (r.url.indexOf(oldDir) === 0) {
                var code = '';
                try { code = readFile(r.url) || ''; } catch (e) { code = ''; }
                if (code) {
                    var newUrl = PY_DIR + r.url.substring(oldDir.length);
                    try {
                        saveFile(newUrl, code);
                        deleteFile(r.url);
                        r.url = newUrl;
                        moved++;
                    } catch (eM) { log('[pyMigrate] 迁移失败 ' + r.url + ': ' + (eM && eM.message ? eM.message : eM)); }
                }
                break;
            }
        }
