function ciliPlayDirect(link){
  try{
    var url=C.abs(C.safe(link));
    var html=C.b64shell(C.get(url));
    var info=C.parseCiliDetail(html);
    if(info.magnets.length){
      var mag='magnet:?xt=urn:btih:'+info.magnets[0];
      if(info.names.length&&info.names[0])mag+='&dn='+encodeURIComponent(info.names[0]);
      return mag;
    }
    return 'toast://未找到磁力链接';
  }catch(e){return 'toast://磁力解析异常: '+C.safe(e.message||e)}
}

