  return url+'#isM3u8##isVideo=true#;{Referer@'+C.REF+'}';
}

function playAcc(raw,cdn){
  var url=C.safe(raw), c=C.safe(cdn);
  if(!url)return 'toast://无播放地址';
  try{
    var api=C.HOST+'/jiasu_m3u8.php?m3u8='+encodeURIComponent(url)+'&cdn='+encodeURIComponent(c)+'&t='+Date.now();
