var IMG_FALLBACK = ["https://sk7vd7ws19jp.gdliren123.com", "https://54d02aljp16.scbixiakj.com", "https://enimg0203.u3wwetf.com", "https://enimg807.m6qzbb4.com"];
var VOD_FALLBACK = ["https://gund9tfy.bx7qxb.com", "https://kgvdwk04dl.upmf83.com", "https://3m5bzkpq.upmf83.com"];

function pickApi() {
    var cached = getItem('apiCache');
    if (cached) return cached;
    var alive = "";
    var dead = 0;
    // 最多容忍 2 条死线就收工：冷启动不能被死域名拖到几十秒
    for (var i = 0; i < ONE_APIS.length && dead < 2; i++) {
        try {
            var res = pdfh(fetch(ONE_APIS[i], { timeout: 4000 }), 'body&&Text');
            if (res === "OK") return ONE_APIS[i];
            if (!alive && res) alive = ONE_APIS[i];
        } catch (e) { dead++; log('探测 ' + ONE_APIS[i] + ' 失败') }
    }
    return alive || ONE_APIS[0];
}

// 域名探活：CDN 根目录 403 也算活（只看连没连上，要求 200 会永远选不到）
function probeDomain(list, path) {
    // 只试前两条、短超时：探不通就直接用列表第一条兜底，别把首屏拖死
    for (var i = 0; i < list.length && i < 2; i++) {
        try {
            var probe = JSON.parse(fetch(list[i] + (path || ''), { withStatusCode: true, timeout: 3500 }));
            if (probe.statusCode > 0) return list[i];
        } catch (e) { log('域名探测失败 ' + list[i]) }
    }
    return "";
}

function bootstrapEnv(force) {
    try {
        var host = force ? pickApi() : getItem('api');
        if (!host) host = getItem('api') || getItem('apiCache') || pickApi() || ONE_APIS[0];
        setItem('api', host);
        setItem('apiCache', host);
        setItem('apiList', JSON.stringify(ONE_APIS));
        if (!force && getItem('imgDomain') && getItem('vodDomain')) return true;
        var apiview = $.require("hanshu");
        var domain = null;
        // bootstrap 也重试一次：冷启动那一下最容易空手而归
        for (var k = 0; k < 2 && !domain; k++) {
            try {
                domain = JSON.parse(apiview.gethtml(host + '/v2.5/bootstrap', BOOT_BODY)).data.domain;
            } catch (e) { log('bootstrap 第 ' + (k + 1) + ' 次失败: ' + e.message) }
        }
        var imgList = (domain && domain.image) || [];
        var vodList = (domain && domain.video) || [];
        if (!imgList.length) imgList = IMG_FALLBACK;
        if (!vodList.length) vodList = VOD_FALLBACK;
        setItem('imgDomainList', JSON.stringify(imgList));
        setItem('vodList', JSON.stringify(vodList));
        setItem('imgDomain', probeDomain(imgList, '/storage/thumb/30877/67fe4fd85b8a9.webp') || imgList[0] || '');
        setItem('vodDomain', probeDomain(vodList, '') || vodList[0] || '');
        return true;
    } catch (e) {
        log('环境自检失败: ' + e.message);
        // 自检挂了也得把兜底域名塞进去，不然封面和播放全空
        if (!getItem('imgDomain')) setItem('imgDomain', IMG_FALLBACK[0]);
        if (!getItem('vodDomain')) setItem('vodDomain', VOD_FALLBACK[0]);
        if (!getItem('apiList')) setItem('apiList', JSON.stringify(ONE_APIS));
        return false;
    }
}
