    ['#FFCDD2', '#B71C1C'],
    ['#F8BBD0', '#880E4F'],
    ['#E1BEE7', '#4A148C'],
    ['#D1C4E9', '#311B92'],
    ['#C5CAE9', '#1A237E'],
    ['#BBDEFB', '#0D47A1'],
    ['#B2EBF2', '#006064'],
    ['#C8E6C9', '#1B5E20'],
    ['#FFF9C4', '#F57F17']
  ],
  rankColors: [
    ['#FFE0B2', '#E65100'],
    ['#FFCCBC', '#BF360C'],
    ['#DCEDC8', '#33691E'],
    ['#B3E5FC', '#01579B'],
    ['#F0F4C3', '#827717']
  ],

  str: function (v) {
    return v === undefined || v === null ? '' : String(v);
  },

  headers: function () {
    return {
      'User-Agent': this.ua,
      'Referer': this.host + '/',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      'Accept-Encoding': 'identity'
    };
  },

  fetchHtml: function (url) {
    return request(url, { headers: this.headers(), timeout: 20000 }) || '';
  },

  absUrl: function (path) {
    path = this.str(path);
    if (!path) return '';
    if (/^https?:\/\//i.test(path)) return path;
    if (path.charAt(0) !== '/') path = '/' + path;
    return this.host + path;
  },

  section: function (title, desc) {
    return { title: title, desc: desc || '', url: 'hiker://empty', col_type: 'text_1' };
  },

  errorItem: function (msg) {
    return { title: '加载失败', desc: this.str(msg || '未知错误'), url: 'hiker://empty', col_type: 'text_center_1' };
  },

  pageNum: function () {
    var page = 1;
    try {
      if (typeof MY_PAGE !== 'undefined' && MY_PAGE) page = Number(MY_PAGE);
      else {
        var mm = String(MY_URL || '').match(/[?&](?:page|fypage)=(\d+)/);
        if (mm) page = Number(mm[1]);
      }
    } catch (e) { page = 1; }
    return !page || page < 1 ? 1 : page;
  },

  parseList: function (html) {
    var list = [];
    var seen = {};
    // <a href="...play/id/ID/..." ... <img src="..." ... <p class="pname">TITLE
    var re = /href="(\/cn\/home\/web\/index\.php\/vod\/play\/id\/(\d+)\/sid\/\d+\/nid\/\d+\.html)"[\s\S]{0,800}?<img[^>]+src="([^"]+)"[\s\S]{0,400}?<p class="pname">\s*([^<]+)/g;
    var m;
    while ((m = re.exec(html))) {
      if (seen[m[2]]) continue;
      seen[m[2]] = 1;
      list.push({
        id: m[2],
        href: m[1],
        img: m[3],
        title: this.str(m[4]).replace(/\s+/g, ' ').trim() || ('视频 ' + m[2])
      });
    }
    if (!list.length) {
      re = /href="(\/cn\/home\/web\/index\.php\/vod\/play\/id\/(\d+)\/[^"]+)"/g;
      while ((m = re.exec(html))) {
        if (seen[m[2]]) continue;
        seen[m[2]] = 1;
        list.push({ id: m[2], href: m[1], img: '', title: '视频 ' + m[2] });
      }
    }
    return list;
  },

  listUrl: function (mode, key, page) {
    page = page || 1;
    // mode: type | rank
    if (mode === 'type') {
      return this.base + '/index.php/vod/type/id/' + key + '/page/' + page + '.html';
    }
    // rank / new
    if (page <= 1) return this.base + '/index.php/label/' + key + '.html';
    return this.base + '/index.php/label/' + key + '/page/' + page + '.html';
  },

  card: function (item) {
    var host = this.host;
    var ua = this.ua;
    var href = this.absUrl(item.href);
    var pic = this.str(item.img);
    if (pic && pic.indexOf('@') < 0) pic = pic + '@Referer=' + host + '/';
    return {
      title: this.str(item.title),
      desc: '点击播放',
      pic_url: pic,
      col_type: 'movie_3_marquee',
      url: $('hiker://empty#noHistory##noLoading#').lazyRule(function (detailUrl, host, ua) {
        try {
          var html = request(detailUrl, {
            headers: {
              'User-Agent': ua,
              'Referer': host + '/',
              'Accept-Encoding': 'identity'
            },
            timeout: 20000
          }) || '';

          var play = '';
          // player_data={"url":"https:\/\/xxx.m3u8",...}
          var m = html.match(/player_data\s*=\s*(\{[\s\S]*?\})\s*;?\s*<\/script>/);
          if (!m) m = html.match(/player_data\s*=\s*(\{[\s\S]*?\})/);
          if (m) {
            try {
              var data = JSON.parse(m[1]);
              play = data.url || data.Url || '';
            } catch (e0) {
              var um = m[1].match(/"url"\s*:\s*"([^"]+)"/);
              if (um) play = um[1].replace(/\\\//g, '/');
            }
          }
          if (!play) {
            m = html.match(/https?:\\\/\\\/[^"']+\.m3u8[^"']*/);
            if (m) play = m[0].replace(/\\\//g, '/');
          }
          if (!play) {
            m = html.match(/https?:\/\/[^\s"'<>]+?\.m3u8[^\s"'<>]*/i);
            if (m) play = m[0];
          }
          if (!play) return 'toast://未解析到播放地址';
          play = String(play).replace(/\\\//g, '/').trim();

          // 主列表 → 子 m3u8 绝对地址
          try {
            var body = request(play, {
              headers: {
                'User-Agent': ua,
                'Referer': host + '/',
                'Accept': '*/*',
                'Accept-Encoding': 'identity'
              },
              timeout: 15000
            }) || '';
            if (body && body.indexOf('#EXT-X-STREAM-INF') >= 0) {
              var origin = (play.match(/^(https?:\/\/[^\/]+)/i) || [])[1] || '';
              var baseDir = play.replace(/\/[^\/]*$/, '/');
              var lines = body.split(/\r?\n/);
              for (var i = 0; i < lines.length; i++) {
                var line = lines[i].trim();
                if (!line || line.charAt(0) === '#') continue;
                if (/^https?:\/\//i.test(line)) { play = line; break; }
                if (line.charAt(0) === '/') { play = origin + line; break; }
                play = baseDir + line;
                break;
              }
            }
          } catch (e1) {}

          // 干净播放串（已验证）
          var clean = String(play || '').trim()
            .replace(/;\{[^}]*\}$/, '')
            .replace(/#isVideo=true#/g, '')
            .trim();
          if (!clean) return 'toast://未找到播放地址';
          return clean + '#isVideo=true#';
        } catch (e) {
          return 'toast://播放解析失败: ' + (e && e.message ? e.message : e);
        }
      }, href, host, ua)
    };
  },

  home: function () {
    var d = [];
    var page = this.pageNum();
    // mode: rank(default) | type
    var mode = getMyVar('fnx_mode', 'rank');
    var key = getMyVar('fnx_key', 'new');

    if (page === 1) {
      // 搜索框
      d.push({
        title: '搜索视频',
        desc: '输入关键词',
        col_type: 'input',
        url: $.toString(function () {
          var kw = (input === undefined || input === null) ? '' : String(input);
          kw = kw.replace(/^\s+|\s+$/g, '');
          if (!kw) return 'toast://请输入关键词';
          try { setItem('fnx_kw', kw); } catch (e) {}
          return $('hiker://empty##fypage#noHistory#').rule(function (keyword) {
            try { setItem('fnx_kw', keyword); } catch (e) {}
            $.require('main').search(keyword);
          }, kw);
        }),
        extra: { defaultValue: getItem('fnx_kw', ''), titleVisible: true }
      });

      // 视频分类：固定 2 排（text_5，每排 5 个；9 个分类 = 5+4）
      var cats = this.categories;
      for (var i = 0; i < cats.length; i++) {
        var selected = mode === 'type' && key === cats[i][1];
        var color = this.catColors[i % this.catColors.length];
        d.push({
          title: selected ? ('““' + cats[i][0] + '””') : cats[i][0],
          col_type: 'text_5',
          url: $('hiker://empty#noHistory##noLoading#').lazyRule(function (id) {
            var curMode = getMyVar('fnx_mode', 'rank');
            var curKey = getMyVar('fnx_key', 'new');
            if (curMode === 'type' && curKey === id) {
              putMyVar('fnx_mode', 'rank');
              putMyVar('fnx_key', 'new');
            } else {
              putMyVar('fnx_mode', 'type');
              putMyVar('fnx_key', id);
            }
            refreshPage(true);
            return 'hiker://empty';
          }, cats[i][1]),
          extra: {
            backgroundColor: selected ? color[1] : color[0],
            textColor: selected ? '#FFFFFF' : color[1]
          }
        });
      }

      // 分隔：避免和排行榜混在同一滑动条
      d.push({ col_type: 'line' });

      // 排行榜：单独一排（5 个 text_5）
      var ranks = this.ranks;
      for (var r = 0; r < ranks.length; r++) {
        var rSel = mode === 'rank' && key === ranks[r][1];
        var rc = this.rankColors[r % this.rankColors.length];
        d.push({
          title: rSel ? ('““' + ranks[r][0] + '””') : ranks[r][0],
          col_type: 'text_5',
          url: $('hiker://empty#noHistory##noLoading#').lazyRule(function (rk) {
            putMyVar('fnx_mode', 'rank');
            putMyVar('fnx_key', rk);
            refreshPage(true);
            return 'hiker://empty';
          }, ranks[r][1]),
          extra: {
            backgroundColor: rSel ? rc[1] : rc[0],
            textColor: rSel ? '#FFFFFF' : rc[1]
          }
        });
      }
    }

    try {
      var url = this.listUrl(mode, key, page);
      var html = this.fetchHtml(url);
      var list = this.parseList(html);
      for (var j = 0; j < list.length; j++) d.push(this.card(list[j]));
      if (!list.length) d.push(this.section('本页没有更多内容', url));
    } catch (e) {
      d.push(this.errorItem(e && e.message ? e.message : e));
    }
    setResult(d);
  },

  search: function (searchKeyword) {
    var d = [];
    var keyword = searchKeyword || getParam('s') || getParam('kw') || getItem('fnx_kw', '');
    keyword = this.str(keyword).trim();
    if (!keyword) {
      setResult([this.section('请输入关键词', '')]);
      return;
    }
    var page = this.pageNum();
    if (page === 1) {
      try { setItem('fnx_kw', keyword); } catch (e) {}
      d.push(this.section('搜索：' + keyword, ''));
    }
    try {
      var url;
      if (page <= 1) {
        url = this.base + '/index.php/vod/search.html?wd=' + encodeURIComponent(keyword);
      } else {
        url = this.base + '/index.php/vod/search/page/' + page + '/wd/' + encodeURIComponent(keyword) + '.html';
      }
      var html = this.fetchHtml(url);
      var list = this.parseList(html);
      if (page === 1) {
        if (!list.length) d.push(this.section('没有找到相关内容', ''));
      }
      for (var i = 0; i < list.length; i++) d.push(this.card(list[i]));
      if (!list.length && page === 1) d.push(this.section('没有找到相关内容', keyword));
    } catch (e) {
      d.push(this.errorItem(e && e.message ? e.message : e));
    }
    setResult(d);
  }
};

$.exports = fnx;
"}]

