  uuid: function() {
    var hex = "0123456789abcdef", s = "";
    for (var i = 0; i < 32; i++) s += hex.charAt(Math.floor(Math.random() * 16));
    return s;
  },
  sha256: function(s) {
    try {
      var md = java.security.MessageDigest.getInstance("SHA-256");
      md.update(new java.lang.String(String(s)).getBytes("UTF-8"));
      var dig = md.digest();
      var hex = [];
      for (var i = 0; i < dig.length; i++) {
        var b = dig[i]; if (b < 0) b += 256;
        var h = b.toString(16); if (h.length < 2) h = "0" + h;
        hex.push(h);
      }
      return hex.join("");
    } catch (e) { return ""; }
  },
  authSign: function(path) {
    var ts = String(Math.floor(new Date().getTime() / 1000));
    var rand = LMS.uuid();
    var uid = "0";
    return ts + "-" + rand + "-" + uid + "-" + LMS.sha256(path + "-" + ts + "-" + rand + "-" + uid + "-" + LMS.privateKey);
  },
  aesDecrypt: function(b64) {
    if (!b64) return "";
    b64 = String(b64).replace(/\s/g, "");
    try {
      var keyBytes = new java.lang.String(LMS.aesKey).getBytes("UTF-8");
      var sk = new javax.crypto.spec.SecretKeySpec(keyBytes, "AES");
      var iv = new javax.crypto.spec.IvParameterSpec(java.util.Arrays.copyOfRange(keyBytes, 0, 16));
      var cipher = javax.crypto.Cipher.getInstance("AES/CBC/NoPadding");
      cipher.init(javax.crypto.Cipher.DECRYPT_MODE, sk, iv);
      var out = cipher.doFinal(android.util.Base64.decode(b64, 0));
      var txt = String(new java.lang.String(out, "UTF-8"));
      var li = Math.max(txt.lastIndexOf("}"), txt.lastIndexOf("]"));
      if (li > 0) {
        txt = txt.substring(0, li + 1);
        var si = txt.indexOf("{"), sj = txt.indexOf("[");
        var start = -1;
        if (si >= 0 && sj >= 0) start = Math.min(si, sj);
        else start = Math.max(si, sj);
        if (start > 0) txt = txt.substring(start);
        return txt;
      }
    } catch (e1) {
      putMyVar("lms_aes_err", String(e1));
    }
    return "";
  },
  headers: function() {
    return {
      "User-Agent": LMS.ua,
      "Accept": "application/json,*/*",
      "Referer": LMS.referer,
