  },
  fetchJson: function(path) {
    var sign = LMS.authSign(path);
    if (!sign || sign.split("-").length < 4) {
      putMyVar("lms_last_err", "authSign fail");
      return null;
    }
    var lastErr = "";
    for (var i = 0; i < LMS.jsonApis.length; i++) {
      try {
        var html = fetch(LMS.jsonApis[i] + path + "?auth_key_sigh=" + sign, { headers: LMS.headers(), timeout: 20000 });
        if (!html || html.length < 5) { lastErr = "empty"; continue; }
        if (html.indexOf("<html") >= 0) { lastErr = "403html"; continue; }
        var j = JSON.parse(html);
        if (j && j.json_data) {
          var dec = LMS.aesDecrypt(j.json_data);
          if (!dec) { lastErr = "aes fail"; continue; }
          try { return JSON.parse(dec); } catch (pe) { lastErr = "json"; continue; }
        }
        return j;
      } catch (e) { lastErr = String(e); }
    }
    putMyVar("lms_last_err", lastErr);
    return null;
  },
  img: function(path) {
    if (!path) return "";
    if (/^https?:\/\//i.test(path)) return path;
    var p = String(path).replace(/\.(webp|jpg|jpeg|png|bmp|gif)(\?.*)?$/i, ".w.js");
    if (!/\.w\.js$/i.test(p) && !/\.js$/i.test(p)) p = p + ".w.js";
    return LMS.imgApis[0] + p + "?auth_key_sigh=" + LMS.authSign(p);
  },
  // 规范化播放路径：有的是 /voss/... 有的是 20250313/...（根路径）
  fullVideoUrl: function(path, host) {
    if (!path) return "";
    if (/^https?:\/\//i.test(path)) return path;
    path = String(path);
    if (path.charAt(0) !== "/") path = "/" + path;
    return (host || LMS.videoApis[0]) + path;
  },
  buildPlay: function(detail) {
    var items = [];
    var list = detail.videoUrlList || [];
    // 优先 h264，再按 quality；跳过 av1（部分设备无密钥/不兼容）
    if (list && list.length) {
      var scored = list.slice().map(function(v) {
        var u = v.videoUrl || "";
        var score = (v.quality || 0);
        if (/av1/i.test(u)) score -= 10000;
        if (/h264/i.test(u)) score += 100;
        return { url: u, score: score, quality: v.quality || 0 };
      });
      scored.sort(function(a, b) { return b.score - a.score; });
      for (var i = 0; i < scored.length; i++) {
        if (scored[i].url) items.push(scored[i].url);
      }
    }
    if (detail.videoUrl) items.push(detail.videoUrl);
    if (detail.videoUrl2) items.push(detail.videoUrl2);
    if (detail.videoUrl3) items.push(detail.videoUrl3);
    var seen = {}, uniq = [];
    for (var j = 0; j < items.length; j++) {
      var p = items[j];
      if (!p || seen[p]) continue;
      seen[p] = 1;
      uniq.push(p);
    }
    return uniq;
  },
  playHeaders: function() {
    return {
