    return {
      title: name || "▶️ 播放",
      url: full + "#isVideo=true#",
      col_type: "text_center_1",
      extra: {
        backgroundColor: "#10b981",
        headers: LMS.playHeaders(),
        ua: LMS.ua
      }
    };
  },

  // 多线路串联：失败自动切下一条（海阔 && 分隔）
  multiPlayUrl: function(paths) {
    if (!paths || !paths.length) return "";
    var parts = [];
    var hosts = LMS.videoApis;
    for (var i = 0; i < paths.length; i++) {
      var p = paths[i];
      if (!p) continue;
      // 跳过 av1 作为主链路靠后
      for (var h = 0; h < hosts.length; h++) {
        var full = LMS.fullVideoUrl(p, hosts[h]);
        var label = "";
        var m = String(p).match(/(\d+)kb/i);
        if (m) label = m[1] + "kb";
        if (/h264/i.test(p)) label += "H264";
        else if (/av1/i.test(p)) label += "AV1";
        else label = label || ("L" + (i + 1));
        if (h > 0) label += "备";
        parts.push(label + "$" + full);
      }
    }
    // 去重
    var seen = {}, out = [];
    for (var k = 0; k < parts.length; k++) {
      var u = parts[k].split("$")[1];
      if (seen[u]) continue;
      seen[u] = 1;
      out.push(parts[k]);
    }
    // 海阔多线路：name$url&&name2$url2#isVideo=true#
    return out.join("&&") + "#isVideo=true#";
  },

  // 根据 id 拉详情并返回可播地址（双 CDN）
  directPlay: function(id) {
    if (!id) return "toast://无视频ID";
    var detail = LMS.fetchJson("/oss/pages/detail/" + id + ".json");
    if (!detail || !detail.id) {
      return "toast://取链失败:" + getMyVar("lms_last_err", "");
    }
    var paths = LMS.buildPlay(detail);
    var best = "";
    for (var i = 0; i < paths.length; i++) {
      if (/av1/i.test(paths[i])) continue;
      best = paths[i];
      break;
    }
    if (!best && paths.length) best = paths[0];
    if (!best) return "toast://暂无播放地址";

    var m3u8 = LMS.fullVideoUrl(best, "https://videos20.redhatxiao.com");
    var m3u8b = LMS.fullVideoUrl(best, "https://videos.caxm119.com:65443");

    var ua = "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36";
    var hdrObj = {
      "User-Agent": ua,
      "Referer": "https://07548876.214573.cc/",
      "Origin": "https://07548876.214573.cc",
      "Accept": "*/*"
    };
    var hdr = JSON.stringify(hdrObj);

    // 本机回环 127.0.0.1：换手机/换局域网 IP 都可用
    // 端口与海阔/嗅觉本地代理一致，默认 52020；不对就 putMyVar("lms_proxy_port","实际端口")
    var port = getMyVar("lms_proxy_port", "52020");
    var base = "http://127.0.0.1:" + port;
    function wrap(u) {
      return base + "/clearM3u8?rule=auto&url=" + encodeURIComponent(u)
        + "&headers=" + encodeURIComponent(hdr) + "#.m3u8";
    }
    return JSON.stringify({
      urls: [wrap(m3u8), wrap(m3u8b)],
      names: ["线路1", "线路2"],
      headers: [hdrObj, hdrObj],
      danmu: "",
      parse: 0
    });
  },
  getChannels: function() { return LMS.channelsData; },
  getTopics: function() { return LMS.topicsData; }
};
$.exports = LMS;
