      });
    }
    return url + '@js=' + this.imageJs;
  },

  decode: function(s){
    if(!s) return '';
    return (''+s)
      .replace(/\\u0026/g,'&')
      .replace(/&amp;/g,'&')
      .replace(/&lt;/g,'<')
      .replace(/&gt;/g,'>')
      .replace(/&quot;/g,'"')
      .replace(/&#34;/g,'"')
      .replace(/&#39;/g,"'")
      .replace(/\\\//g,'/');
  },

  // 卡片：只用 img 的 src=（避开 data-preview-src）
  parseCards: function(html){
    var list = [], seen = {};
    if(!html) return list;
    // 整块卡片：懒加载真实图在 data-src
    var re = /<a class="card" href="([^"]+)"([^>]*)>([\s\S]*?)<\/a>/g;
    var m;
    while((m = re.exec(html))){
      var url = m[1];
      if(seen[url]) continue;
      var block = m[3] || '';
      if(block.indexOf('p-img') < 0 && block.indexOf('poster') < 0) continue;
      seen[url] = 1;
      var attrs = m[2] || '';
      var nm = attrs.match(/data-track-item-name="([^"]*)"/);
      var title = nm ? this.decode(nm[1]) : '';
      if(!title){
        var h3 = block.match(/<h3>([^<]+)<\/h3>/);
        if(h3) title = this.decode(h3[1]);
      }
      var img = '';
      var ds = block.match(/data-src="(https?:\/\/[^"]+)"/);
      if(ds) img = ds[1];
      if(!img){
        var sm = block.match(/\ssrc="(https?:\/\/[^"]+)"/);
        if(sm && !/\.m3u8/i.test(sm[1]) && sm[1].indexOf('data:') !== 0) img = sm[1];
      }
      // 站点自有海报兜底
      if(!img){
        var idm = attrs.match(/data-track-item-id="([^"]+)"/);
        var typ = attrs.match(/data-track-item-type="([^"]+)"/);
        if(idm){
          var t = (typ && typ[1] === 'comic') ? 'comic' : (typ && typ[1] === 'novel') ? 'novel' : 'video';
          img = this.host + '/media/posters/' + t + '/' + idm[1];
        }
      }
      if(img) img = this.decode(img);
      if(/\.m3u8/i.test(img) || (img && img.indexOf('data:') === 0)) img = '';
      list.push({ url: url, title: title || '作品', img: this.abs(img) });
    }
    return list;
  },

  // 首页按分区取卡片并去重（官方推荐 / 热播 / 各栏目）
  parseHome: function(html){
    var all = this.parseCards(html);
    // 已在 parseCards 内按 URL 去重
    return all;
  },

  // 从详情页解析全部选集
  parseEpisodes: function(html, itemUrl){
    var eps = [], seen = {};
    if(!html) return eps;
    var base = (itemUrl || '').replace(/\/$/, '');

    // 1) ep-grid + data-chunk（最准）
    var re = /<a[^>]+href="([^"]+)"[^>]*data-chunk="[^"]*"[^>]*>\s*(\d+)\s*<\/a>/g;
    var m;
    while((m = re.exec(html))){
      if(seen[m[2]]) continue;
      seen[m[2]] = 1;
      eps.push({ url: m[1], n: m[2] });
    }

    // 2) 同路径 /N/
    if(!eps.length && base){
      var esc = base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      re = new RegExp('href="(' + esc + '/(\\d+)/)"', 'g');
      while((m = re.exec(html))){
        if(seen[m[2]]) continue;
        seen[m[2]] = 1;
        eps.push({ url: m[1], n: m[2] });
      }
    }

    // 3) 通用：详情同目录下数字分集
    if(!eps.length && base){
      re = /href="(https:\/\/91crdj\.com\/[^"]+\/(\d+)\/)"/g;
      var prefix = base.split('/').slice(0, -1).join('/');
      while((m = re.exec(html))){
        if(m[1].indexOf(base + '/') !== 0 && m[1].indexOf(base) < 0) continue;
        if(seen[m[2]]) continue;
        // 只要 base/数字/
        if(m[1].replace(/\/$/, '') === base) continue;
        seen[m[2]] = 1;
        eps.push({ url: m[1], n: m[2] });
      }
    }

    eps.sort(function(a, b){ return parseInt(a.n, 10) - parseInt(b.n, 10); });
    return eps;
  },

  // 完整 m3u8（含 via_bm）；本站通常只有一路清晰度
  extractM3u8: function(html){
    if(!html) return '';
    var m = html.match(/"src"\s*:\s*"(https:[^"]+\.m3u8[^"]*)"/);
    if(m) return this.decode(m[1]);
    m = html.match(/https:\/\/yd-hls\.[^"'\s\\]+via_bm=[a-zA-Z0-9]+/);
    if(m) return this.decode(m[0]);
    m = html.match(/https:\/\/[^"'\s\\]+?\.m3u8\?[^"'\s\\]+/);
    if(m) return this.decode(m[0]);
    return '';
  },

  toPlay: function(play){
    if(!play) return 'toast://未找到播放地址';
    play = this.decode(play);
    if(play.indexOf('via_bm=') < 0 && play.indexOf('auth_key=') >= 0){
      play += (play.indexOf('?') >= 0 ? '&' : '?') + 'v=3&time=0&via=91crdj&via_bm=dx';
    }
    var headers = {
      'User-Agent': this.ua,
      'Referer': this.host + '/',
      'Origin': this.host
    };
    try{
      var cached = cacheM3u8(play, { headers: headers }, '', '');
      if(cached && ('' + cached).indexOf('file://') === 0) return cached;
    }catch(e1){}
    try{
      if(typeof getProxy === 'function'){
        return getProxy(true) + 'clearM3u8?rule=auto&url=' + encodeURIComponent(play) +
          '&headers=' + encodeURIComponent(JSON.stringify(headers)) + '#.m3u8';
      }
    }catch(e2){}
    return play + '#isVideo=true#';
