    search: function(){
    var d = [], page = 1;
    try{ if(typeof MY_PAGE !== 'undefined' && MY_PAGE) page = parseInt(MY_PAGE) || 1; }catch(e){}
    try{
      if(MY_URL){
        var mp = ('' + MY_URL).match(/[?&]page=(\d+)/);
        if(mp) page = parseInt(mp[1]) || 1;
        // fypage 形式：hiker://empty##2
        var mp2 = ('' + MY_URL).match(/##(\d+)/);
        if(mp2) page = parseInt(mp2[1]) || page;
      }
    }catch(e){}
    if(!(page > 0)) page = 1;

    function decKw(s){
      s = String(s || '').replace(/^\s+|\s+$/g, '');
      if(!s) return '';
      var prev = s;
      for(var i = 0; i < 4; i++){
        try{
          if(!/%[0-9A-Fa-f]{2}/.test(prev)) break;
          var d0 = decodeURIComponent(prev.replace(/\+/g, ' '));
          if(d0 === prev) break;
          prev = d0;
        }catch(e){ break; }
      }
      // 去掉意外的二次编码残留
      if(prev.indexOf('%') >= 0 && !/%[0-9A-Fa-f]{2}/.test(prev)) {
        /* ignore */
      }
      return prev;
    }

    // 首页 X5 用 fba.putVar 存明文；本页搜索框用 putMyVar
    var kw = '';
    try{ kw = decKw(getVar('crdj_kw', '') || ''); }catch(e){}
    if(!kw){ try{ kw = decKw(getMyVar('crdj_kw', '') || ''); }catch(e){} }
    if(!kw){ try{ if(typeof input !== 'undefined' && input) kw = decKw(input); }catch(e){} }
    if(!kw){
      try{
        if(typeof getParam === 'function')
          kw = decKw(getParam('s') || getParam('wd') || getParam('keyword') || '');
      }catch(e){}
    }
    if(!kw){
      try{
        if(MY_URL){
          var km = ('' + MY_URL).match(/[?&](?:s|wd|keyword)=([^&#]+)/);
          if(km) kw = decKw(km[1]);
        }
      }catch(e){}
    }
    kw = decKw(kw);
    if(kw){
      try{ putMyVar('crdj_kw', kw); }catch(e){}
      try{ putVar('crdj_kw', kw); }catch(e){}
    }

    if(page === 1){
      d.push({
        title: '搜索',
        url: $.toString(function(){
          if(!input) return 'toast://请输入关键词';
          var k = String(input).replace(/^\s+|\s+$/g, '');
          try{
            while(/%[0-9A-Fa-f]{2}/.test(k)){
              var n = decodeURIComponent(k.replace(/\+/g, ' '));
              if(n === k) break;
              k = n;
            }
          }catch(e){}
          putMyVar('crdj_kw', k);
          try{ putVar('crdj_kw', k); }catch(e2){}
          refreshPage(true);
          return 'hiker://empty';
        }),
        col_type: 'input',
        extra: { hint: '搜索作品', defaultValue: kw || '' }
      });
      d.push({ col_type: 'blank_block' });
    }

    if(!kw){ setResult(d); return; }

    // 源站搜索基本一页出完，无 /page/N（会 404）；第2页起直接结束翻页
    if(page > 1){
      setResult([]);
      return;
    }

    var enc = encodeURIComponent(kw);
    var url = this.host + '/search/' + enc + '/';
    var cards = this.parseCards(this.get(url));
    if(!cards.length){
      d.push({ title: '没有结果 · ' + kw, url: 'hiker://empty', col_type: 'text_center_1' });
    }else{
      d.push({ title: '🔍 “' + kw + '” · ' + cards.length + ' 条', url: 'hiker://empty', col_type: 'rich_text' });
      this.pushCards(d, cards, '');
    }
    setResult(d);
  },

