        'function goSearch(){var el=document.getElementById("kw"),kw=(el.value||"").trim();if(!kw){el.focus();return false}try{fba.putVar("crdj_kw",kw);try{fba.putMyVar&&fba.putMyVar("crdj_kw",kw)}catch(e0){};var rn=' + JSON.stringify(currentRuleTitle) + ';fba.open(JSON.stringify({rule:rn,title:"搜索",url:"hiker://page/search?rule="+rn+"&s="+encodeURIComponent(kw)+"#noHistory#",group:"",col_type:"",findRule:"",preRule:"",extra:{}}))}catch(e){alert("搜索页面打开失败："+e.message)}return false}' +
