js:
var d = [];
var HOST = getMyVar("wgcg_host", "https://videoh5.86027a.xyz");
var UA = "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36";
var PAGE = 20;

function wgcgHdr(tok) {
  var h = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/plain, */*",
    "cid": "1",
    "timestamp": String(Math.floor(Date.now() / 1000)),
    "Accept-Language": "tw",
    "User-Agent": UA,
    "Origin": HOST,
    "Referer": HOST + "/"
  };
  if (tok) h["token"] = tok;
  return h;
}
function wgcgToken() {
  var tok = getMyVar("wgcg_token", "");
  var ts = parseInt(getMyVar("wgcg_token_ts", "0"), 10) || 0;
  if (tok && (Date.now() - ts < 6 * 3600 * 1000)) return tok;
  var mc = "", hex = "0123456789abcdef";
  for (var i = 0; i < 32; i++) mc += hex.charAt(Math.floor(Math.random() * 16));
  try {
    var reg = JSON.parse(fetch(HOST + "/api/user/dunGustRegister", {
      method: "POST", headers: wgcgHdr(""), body: JSON.stringify({ machine_code: mc })
    }) || "{}");
    tok = ((reg.data || {}).token) || "";
    if (tok) {
      putMyVar("wgcg_token", tok);
      putMyVar("wgcg_token_ts", String(Date.now()));
    }
  } catch (e) {}
  return tok || "";
}
function wgcgPost(path, obj) {
  var tok = wgcgToken();
  try {
    return JSON.parse(fetch(HOST + "/api/" + path, {
      method: "POST", headers: wgcgHdr(tok), body: JSON.stringify(obj || {})
    }) || "{}");
  } catch (e2) { return {}; }
}
function wgcgVHost() {
  var v = getMyVar("wgcg_vhost", "");
  var ts = parseInt(getMyVar("wgcg_vhost_ts", "0"), 10) || 0;
  if (v && (Date.now() - ts < 3600 * 1000)) return v;
  try {
    var j = wgcgPost("user/getVideoUrl", {});
    v = String(((j.data || {}).video_url) || "").replace(/\/$/, "");
    if (v) {
      putMyVar("wgcg_vhost", v);
      putMyVar("wgcg_vhost_ts", String(Date.now()));
    }
  } catch (e) {}
  return v || "";
}
function wgcgImg(c) {
  c = String(c || "").trim();
  if (!c) return "";
  if (c.indexOf("http") === 0) return c + (/\.(jpg|jpeg|png|webp)/i.test(c) ? "" : "#.jpg");
  var vh = wgcgVHost();
  if (!vh) return "";
  return vh + (c.charAt(0) === "/" ? c : "/" + c) + "#.jpg";
}
function wgcgDur(sec) {
  try { sec = parseInt(sec, 10) || 0; } catch (e) { return ""; }
  if (sec <= 0) return "";
  var m = Math.floor(sec / 60), s = sec % 60;
  return (m < 10 ? "0" : "") + m + ":" + (s < 10 ? "0" : "") + s;
}
function wgcgPlayRule(vid) {
  return $("hiker://empty").lazyRule((vid, HOST, UA) => {
    function hdr(tok) {
      var h = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "cid": "1",
        "timestamp": String(Math.floor(Date.now() / 1000)),
        "Accept-Language": "tw",
        "User-Agent": UA,
        "Origin": HOST,
        "Referer": HOST + "/"
      };
      if (tok) h.token = tok;
      return h;
    }
    function post(path, obj) {
      var tok = getMyVar("wgcg_token", "");
      try {
        return JSON.parse(fetch(HOST + "/api/" + path, {
          method: "POST",
          headers: hdr(tok),
          body: JSON.stringify(obj || {})
        }) || "{}");
      } catch (e) { return {}; }
    }
    function absUrl(base, path) {
      path = String(path || "").trim().replace(/\\/g, "/");
      if (!path) return "";
      if (/^https?:\/\//i.test(path)) return path;
      base = String(base || "").replace(/\/$/, "");
      if (path.charAt(0) === "/") return base + path;
      return base + "/" + path;
    }
    try {
      if (!getMyVar("wgcg_token", "")) {
        var hex = "0123456789abcdef", mc = "";
        for (var i = 0; i < 32; i++) mc += hex.charAt(Math.floor(Math.random() * 16));
        var reg = JSON.parse(fetch(HOST + "/api/user/dunGustRegister", {
          method: "POST", headers: hdr(""), body: JSON.stringify({ machine_code: mc })
        }) || "{}");
        var tk = ((reg.data || {}).token) || "";
        if (tk) { putMyVar("wgcg_token", tk); putMyVar("wgcg_token_ts", String(Date.now())); }
      }
      var det = post("video/v2/detail", { id: parseInt(vid, 10) || vid });
      var dd = det.data || {};
      var pu = String(dd.pu || dd.play_url || "").trim();
      if (!pu) return "toast://暂无播放地址";

      var vh = String((((post("user/getVideoUrl", {}).data) || {}).video_url) || getMyVar("wgcg_vhost", "")).replace(/\/$/, "");
      if (!vh) return "toast://播放域名获取失败";
      putMyVar("wgcg_vhost", vh);

      var master = absUrl(vh, pu);
      var play = master;

      // 解析主 m3u8，取最高带宽分线路（避免相对路径/广告中转）
      try {
        var m3 = fetch(master, {
          headers: {
            "User-Agent": UA,
            "Referer": HOST + "/",
            "Origin": HOST,
            "Accept": "*/*"
          }
        }) || "";
        if (m3.indexOf("#EXTM3U") >= 0) {
          var lines = m3.split(/\r?\n/);
          var bestBw = -1, bestPath = "";
          var pendingBw = 0;
          for (var li = 0; li < lines.length; li++) {
            var line = lines[li].trim();
            if (line.indexOf("#EXT-X-STREAM-INF:") === 0) {
              var bm = line.match(/BANDWIDTH=(\d+)/i);
              pendingBw = bm ? parseInt(bm[1], 10) : 0;
            } else if (line && line.charAt(0) !== "#") {
              if (pendingBw >= bestBw) {
                bestBw = pendingBw;
                bestPath = line;
              }
              pendingBw = 0;
            }
          }
          if (bestPath) {
            play = absUrl(vh, bestPath);
            // 修正偶发双斜杠
            play = play.replace(/([^:])\/\//g, "$1/");
          }
        }
      } catch (eM) {}

      // 与 TVBox 插件一致：直链 + UA/Referer（不要 JSON 多包一层，减少被清流代理改写）
      var head = {
        "User-Agent": UA,
        "Referer": HOST + "/",
        "Origin": HOST,
        "Accept": "*/*",
        "Accept-Encoding": "identity"
      };
      return JSON.stringify({
        urls: [play],
        names: ["高清"],
        headers: [head],
        parse: 0
      });
    } catch (e2) {
      return "toast://解析失败";
    }
  }, String(vid), HOST, UA);
}
function wgcgPushCard(arr, it) {
  if (!it || !it.id) return;
  var title = String(it.t || it.title || "").trim();
  if (!title) return;
  var img = wgcgImg(it.c || it.cover);
  var desc = [];
  var dur = wgcgDur(it.tm);
  if (dur) desc.push(dur);
  if (parseInt(it.iv, 10) === 1) desc.push("VIP");
  arr.push({
    title: title,
    desc: desc.join(" · "),
    img: img ? (img + "@Referer=" + HOST + "/@User-Agent=" + UA) : "",
    url: wgcgPlayRule(it.id),
    col_type: "movie_2"
  });
}
function wgcgRows(j) {
  if (!j || !j.data) return [];
  if (Array.isArray(j.data)) return j.data;
  return j.data.l || j.data.list || [];
}

var page = 1;
try { page = parseInt(String(MY_PAGE), 10) || 1; } catch (e) { page = 1; }
if (page < 1) page = 1;

var mode = getMyVar("wgcg_mode", "home");
var cid = getMyVar("wgcg_cid", "");
var cname = getMyVar("wgcg_cname", "");

if (page === 1) {
  wgcgToken();
  wgcgVHost();

  d.push({
    title: "🔍",
    url: $.toString(() => {
      var kw = String(input || "").trim();
      if (!kw) { toast("请输入关键词"); return "hiker://empty"; }
      putMyVar("wgcg_kw", kw);
      putMyVar("wgcg_mode", "search");
      return "hiker://page/list?p=fypage";
    }),
    desc: "搜索网页吃瓜...",
    col_type: "input",
    extra: { defaultValue: getMyVar("wgcg_kw", "") || "" }
  });

  // 分类条：接口只有一层，无子分类；过滤空分类（缓存）
  var goodCats = [];
  try { goodCats = JSON.parse(getMyVar("wgcg_good_cats", "[]") || "[]"); } catch (e0) { goodCats = []; }
  if (!goodCats.length) {
    var cats = [];
    try {
      var cj = wgcgPost("video/category", {});
      cats = Array.isArray(cj.data) ? cj.data : [];
    } catch (e1) { cats = []; }
    for (var i = 0; i < cats.length; i++) {
      var c = cats[i];
      if (!c || c.id == null) continue;
      try {
        var tr = wgcgRows(wgcgPost("video/v2/list", {
          page: 1, page_size: 1, category_id: parseInt(c.id, 10) || c.id
        }));
        if (tr.length > 0) goodCats.push({ id: c.id, name: String(c.name || "") });
      } catch (e2) {}
    }
    if (!goodCats.length) {
      for (var i3 = 0; i3 < cats.length; i3++) {
        if (cats[i3] && cats[i3].id != null)
          goodCats.push({ id: cats[i3].id, name: String(cats[i3].name || "") });
      }
    }
    putMyVar("wgcg_good_cats", JSON.stringify(goodCats));
  }
  putMyVar("wgcg_cats", JSON.stringify(goodCats));

  d.push({
    title: (!cid && mode !== "cate") ? "““””<font color='#1aad19'><b>推荐</b></font>" : "推荐",
    url: $("#noLoading#").lazyRule(() => {
      putMyVar("wgcg_mode", "home");
      putMyVar("wgcg_cid", "");
      putMyVar("wgcg_cname", "");
      refreshPage(false);
      return "hiker://empty";
    }),
    col_type: "scroll_button"
  });
  for (var i2 = 0; i2 < goodCats.length; i2++) {
    var cc = goodCats[i2];
    var on = (mode === "cate" && String(cid) === String(cc.id));
    d.push({
      title: on ? ("““””<font color='#1aad19'><b>" + cc.name + "</b></font>") : cc.name,
      url: $("#noLoading#").lazyRule((id, name) => {
        putMyVar("wgcg_mode", "cate");
        putMyVar("wgcg_cid", String(id));
        putMyVar("wgcg_cname", String(name));
        refreshPage(false);
        return "hiker://empty";
      }, cc.id, cc.name),
      col_type: "scroll_button"
    });
  }
  d.push({ col_type: "blank_block" });
}

// ---------- 内容区 ----------
if (mode === "cate" && cid) {
  // 分类列表：按页请求，下滑 MY_PAGE++ 加载下一页
  var lj = wgcgPost("video/v2/list", {
    page: page,
    page_size: PAGE,
    category_id: parseInt(cid, 10) || cid
  });
  var rows = wgcgRows(lj);
  log("wgcg cate id=" + cid + " page=" + page + " n=" + rows.length);
  if (page === 1 && cname) {
    d.push({ title: "📂 " + cname, url: "hiker://empty", col_type: "rich_text" });
  }
