        iv: iv,
        mode: CryptoJS.mode.CBC,
        padding: CryptoJS.pad.Pkcs7 // 注意这里应该是CryptoJS.pad.NoPadding
    });
    if (decrypt) {
        let decryptedStr = decrypt.toString(CryptoJS.enc.Utf8);
        return decryptedStr;
    } else {
        // 解密失败，返回null或错误信息
        return null;
    }
}


