                        $.require("configs").saveJson(arr);
                        clearItem("rule");
                        refreshPage(true);
                        return "toast://删除成功";
                    }, name)
                });
            }, name);
        }
        if (Array.isArray(result) && result.length === 1) {
            result = result[0];
        }
        if (typeof result === "string") {
            ciliUrl = result;
        } else if (Array.isArray(result) && result.length) {
            let isStr = typeof(result[0]) === "string";
            let select = result;
            if (!isStr) {
