function getCompleteRule(rule) {
    let find = new Function("s", "page", "user", "basicUrl", rule.find);
    rule.find = (s, page) => find(s, page, rule.user || {}, rule.basicUrl || "");
    if (rule.findAliUrl) {
        rule.findAliUrl = new Function("input", "basicUrl", rule.findAliUrl);
    }
    return rule;
}
$.exports.carryRule = function(rule, s, page, searchMode, openMode) {
    rule = getCompleteRule(rule);
    let list = rule.find(s, page);
    if (!list) return [];
    let urlLazy = $("").lazyRule(doubleTreating, {
        openMode: openMode,
        findAliUrl: rule.findAliUrl,
        basicUrl: rule.basicUrl,
        name: rule.name
    }, getModeUrl);
    let descTips = "““””" + rule.name.fontcolor("#f13b66a") + "&nbsp;";
    let resList = [];

    //关键词高亮
    function highlightKeywords(text, keywords) {
        //keywords = keywords.split("");
        match = keywords.match(/(\d*?[a-zA-Z]*)([-_\s]?)(\d*)/)
        ww = !match[1] ? "🐟" : match[1]
        dd = !match[2] ? "🦈" : match[2]
        ss = !match[3] ? "🐬" : match[3]
        keywords = [keywords, ww, dd, ss];
        keywords = Array.from(new Set(keywords)); // log(keywords)
        keywords.forEach(function(keyword) {
            // 对关键字进行转义以避免特殊字符在正则中的问题，然后建立用于匹配的正则表达式
            var escapedKeyword = keyword.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
            // 高亮关键词，排除HTML标签内的匹配
            var pattern = new RegExp('(?!<[^<>]*)(' + escapedKeyword + ')(?![^<>]*>)', 'gi');
            text = text.replace(pattern, function(match) {
                return match.fontcolor('#FF00FF');
            });
        });
        return text;
    }
    for (let it of list) {
        if (it.skip) {
            resList.push(it);
            continue;
        }
        if (searchMode && !searchContains(it.title, s, true)) continue;
        it.url = rule.findAliUrl ? it.url + urlLazy : $("#noLoading#").lazyRule(getModeUrl, it.url, it.sharePwd || "", openMode);
