    var d1 = new Date(Number(date1));
    var d2 = new Date(Number(date2));
    // 获取完整日期部分
    var start = new Date(d1.getFullYear(), d1.getMonth(), d1.getDate());
    var end = new Date(d2.getFullYear(), d2.getMonth(), d2.getDate());    
