// 聚BT论坛 https://bbs.jubt.top/
// https://1jubt.top/
// https://1jubt.xyz/
// https://jubt.gitlab.io/home/

function requestData() {
    log('地址发布页：' + MY_RULE.url.slice(15))
    let datas = [],
        success = false,
        urls = parseDomForArray(request(MY_RULE.url.slice(15)), 'tbody&&tr')
    for (let url of urls) {
        url = parseDomForHtml(url, 'a&&href') + '/cn/index.html'
        log('请求地址：' + url)
        datas = request(url)
        if (datas) try {
            datas = datas.match(/<h4(?:(?!h4).)*h4><div(?:(?!h4).)*div>/g)
                .slice(1).map((v) => ({
                    title: parseDomForHtml(v, 'h4&&Text'),
                    url: parseDomForHtml(v, 'h4&&i&&id'),
                    children: parseDomForArray('<body>' + v + '</body>', 'body&&.row>div')
                        .map((v) => ({
                            title: parseDomForHtml(v, 'a,1&&Text').split(' | ')[0],
                            url: parseDomForHtml(v, 'div,1&&data-original-title')
                        })),
                }))
            datas.unshift(new Date().toISOString())
            saveFile('dataCache.json', JSON.stringify(datas), 0)
            success = true
            break
        } catch (e) {}
    }
    log('更新数据' + (success ? '成功' : '失败'))
    return success
}
let datas = readFile('dataCache.json', false)
if (datas) {
    datas = JSON.parse(datas)
    if (Date.now() - Date.parse(datas[0]) > 7 * 24 * 60 * 60000)
        (new java.lang.Thread(function() {
            if (requestData()) {
                confirm({ title: '聚BT 提示', content: '后台更新数据成功' })
                refreshPage(false)
            } else {
                datas[0] = new Date().toISOString()
                saveFile('dataCache.json', JSON.stringify(datas), 0)
            }
        })).start()
} else if (!requestData()) {
    confirm({ title: '聚BT 提示', content: '获取数据失败，请刷新重试' })
}

