let myCollection_el = [],
    searchMode = getVar('myCollection-searchMode', ''),
    [_, pageNum, keyword] = MY_URL.split('##'),
    RULE = $.require('hiker://page/dataLoad?rule=' + getItem('myCollection')).filter((v) => v.search_url)
pageNum = parseInt(pageNum)
if (!searchMode && pageNum > RULE.length) setResult([])

let searchCount = { title: '⬆ 已搜索了' + pageNum + '个小程序 ⬆\n⬇ 下面还有' + (RULE.length - pageNum) + '个小程序 ⬇' }
RULE = searchMode ? RULE.find((v) => v.title == searchMode) : RULE[pageNum - 1]
// 处理MY_URL和MY_RULE
MY_RULE.version = RULE.version
MY_RULE.group = RULE.group
MY_RULE.title = RULE.title
MY_RULE.ua = RULE.ua
MY_RULE.col_type = RULE.col_type
MY_RULE.detail_col_type = RULE.sdetail_col_type
MY_RULE.find_rule = RULE.searchFind
MY_RULE.detail_find_rule = ['', '*'].includes(RULE.sdetail_find_rule) ? RULE.detail_find_rule : RULE.sdetail_find_rule
MY_RULE.preRule = RULE.preRule
MY_RULE.pageList = JSON.parse(RULE.pages || '[]')
MY_RULE.pages = JSON.stringify(MY_RULE.pageList)
MY_RULE.last_chapter_rule = RULE.last_chapter_rule
MY_RULE.params = {}

const { runCode, urlParse } = $.require('hiker://page/utility?rule=' + getItem('myCollection'))
var { MY_URL, indexHtml } = urlParse(RULE.search_url, searchMode ? pageNum : 1, (url) => {
    url[0] = url[0].replace(url[0].includes('%%') ? /%%/g : /\*\*/g, encodeStr(keyword, url[2]))
})
MY_RULE.url = MY_URL
// 正文解析
if (pageNum == 1) eval(MY_RULE.preRule)
if (MY_RULE.find_rule.startsWith('js:')) {
    function getUrl() {
        return MY_URL
    }

    function getResCode() {
        return indexHtml
    }

    function setResult(el, param1, param2, param3) {
        param1 = CALLBACK_KEY
        param2 = MY_RULE
        param3 = MY_TYPE
        if (Array.isArray(el.data)) el = el.data
        log(el)
        Array.prototype.push.apply(myCollection_el, el.map((v) => {
            let RULE = Object.assign({}, MY_RULE)

            if (!v.url) {
                return v
            } else if (v.url.includes('@lazyRule=')) {
                v.url = v.url.replace('.js:', '.js:\nif(MY_RULE)Object.assign(MY_RULE,' + $.stringify({ title: MY_RULE.title, pages: MY_RULE.pages, pageList: MY_RULE.pageList, find_rule: '', params: '' }) + ');')
                return v
            } else if (v.url.includes('@rule=')) {
                let [_, url, rule] = v.url.match(/^([\s\S]*?)@rule=([\s\S]*)$/)
                v.url = url
                RULE.detail_find_rule = rule
                RULE.detail_col_type = MY_RULE.col_type
            } else if (v.url.startsWith('hiker://page/')) {
                if (v.url.includes('rule=') || (v.extra || {}).rule)
                    return v
                let path = v.url.split('#')[0].match(/^hiker:\/\/page\/(.+?)(?:\?.*)?$/)[1],
                    subPage = MY_RULE.pageList.find(v => v.path == path)
                RULE.detail_find_rule = subPage.rule
                RULE.detail_col_type = subPage.col_type
                RULE.params = v.extra || {}
            } else if (!MY_RULE.detail_find_rule) { return v }
            v.extra = { url: v.url, RULE: RULE, pageTitle: v.title  }
            v.url = 'hiker://page/detailLoad?rule=' + getItem('myCollection')
            return v
        }))
        if (!searchMode) myCollection_el.push(searchCount)
        method_setResult.invoke(javaContext, myCollection_el, param1, param2, param3)
    }

    function setHomeResult(a, param1, param2, param3) {
        setResult(a, param1, param2, param3)
    }

    function setSearchResult(a, param1, param2, param3) {
        setResult(a, param1, param2, param3)
    }

    eval(MY_RULE.find_rule.slice(3))
} else {
    let findRule = MY_RULE.find_rule.split(';')
    parseDomForArray(indexHtml, findRule.shift()).forEach((data) => {
        let [title, url, desc, content, img] = findRule.map((v, i) => {
                try {
                    if (v == '*') return ''
                    else v = (i == 1 || i == 4) ?
                        parseDom(data, v) :
                        parseDomForHtml(data, v)
                    if (i != 1) v = runCode(v)
                    return v
                } catch (e) {}
            }),
            res = {
                title: title,
                url: url,
                desc: desc,
                content: content,
                img: img
            }
        if (res.url) {
            if (res.url.includes('@lazyRule=')) {
                res.url = res.url.replace('.js:', '.js:\nif(MY_RULE)Object.assign(MY_RULE,' + $.stringify({ title: MY_RULE.title, pages: MY_RULE.pages, pageList: MY_RULE.pageList, find_rule: '', params: '' }) + ');')
            } else if (MY_RULE.detail_find_rule) {
                res.url = 'hiker://page/detailLoad?rule=' + getItem('myCollection')
                res.extra = { url: url, RULE: MY_RULE, pageTitle: title  }
            }
        }
        myCollection_el.push(res)
        if (!searchMode) myCollection_el.push(searchCount)
    })
    setResult(myCollection_el)
}

