    //JPA等线路挂了已屏蔽，需要可去二级恢复
    //TV线路//FST线路//VOE线路//ST线路//DS线路//VTU线路
    // 定义一个解析分辨率的函数
    function getResolution(name) {
        var match = name.match(/(\d+)/); // 提取降级分辨率
        return match ? parseInt(match[1], 10) : 0; // 如果没有匹配则返回0
    }
