                },
                cancel: () => {
                    return 'toast://你将无法使用本程序的最新功能'
                },
            })
        } else {
            return 'latest'
        }
    } catch (e) {
        toast('GG，更新失效了！')
    }
}

// 去除提交更新信息方法，再上传云剪贴板，返回最新版本的小程序云口令
function submit_latest_rule() {
    // 先获取原规则内容
    let submit_update_origin_my_rule = MY_RULE

    // 正则命中上传更新方法内容
    let submit_update_info_code_regex = /submit_update_info\(.*?\)/g

    // json规则转字符串规则,然后正则替换删除所有上传更新方法内容
    let submit_update_replace_my_rule = JSON.stringify(submit_update_origin_my_rule).replace(
        submit_update_info_code_regex,
        ''
    )

    // 构造上传的最终规则内容
    let submit_update_my_rule =
        `海阔视界规则分享，当前分享的是：小程序￥home_rule_v2￥base64://@${MY_RULE.title}@` +
        base64Encode(submit_update_replace_my_rule)

    // 上传内容到剪贴板
    let update_info_url = fetch('https://pasteme.tyrantg.com/api/create', {
        body: {
            lang: 'plain',
            content: submit_update_my_rule
        },
    })
    update_info_url = JSON.parse(update_info_url)
    update_info_url = '云6oooole/xxxxxx/' + update_info_url.data.path
    // 复制和返回云剪贴板地址
    copy('update_info_url')
    return update_info_url
}

// 提交更新信息
function submit_update_info(flag, content, ad) {
    if (flag) {
        let update_info = {
            version: MY_RULE.version,
            ad: ad ? ad : '',
            content: content ? content : '',
            url: submit_latest_rule().split('\n')[0],
        }
