    }
};

// 获取分类数据
function getCategories() {
    const baseCates = pdfa(html, 大类定位);
    return typeof 拼接分类 !== 'undefined' && 拼接分类 
        ? baseCates.concat(pdfa(html, 拼接分类))
        : baseCates;
}

// 创建分类按钮
function createCategoryButton(item, key, index, resetOthers, currentSelected) {
    let title = pdfh(item, 分类标题);

    // 安全检查排除变量
    if (typeof 排除 !== 'undefined' && 排除) {
        title = title.replace(new RegExp(排除, "g"), "");
    }

    const isSelected = key.toString() === currentSelected[index];
    const displayTitle = isSelected ? `““””${title.fontcolor(CONFIG.COLORS.category)}` : title;

    return {
        title: displayTitle,
        url: $(pd(item, 分类链接) + '#noLoading#').lazyRule((params) => {
            const newCate = params.currentSelected.map((c, i) => 
                params.resetOthers 
                    ? (i === params.index ? params.key.toString() : "0")
                    : (i === params.index ? params.key.toString() : c)
