            index: index, 
            key: key, 
            resetOthers: resetOthers 
        }),
        col_type: 'scroll_button',
    };
}

// 创建折叠按钮
function createFoldButton(currentFoldState) {
    const isFolded = currentFoldState === '1';
    const icon = isFolded ? CONFIG.FOLD_ICONS.open : CONFIG.FOLD_ICONS.close;
    const color = isFolded ? CONFIG.COLORS.fold : CONFIG.COLORS.unfold;

    return {
        title: `““””<b>${icon.fontcolor(color)}</b>`,
        url: $().lazyRule((f) => {
            putMyVar(MY_RULE.group, f === '1' ? '0' : '1');
            refreshPage(false);
            return "hiker://empty";
        }, currentFoldState),
        col_type: 'scroll_button',
    };
}

// 主函数
function buildCategoryUI() {
    const result = [];
    const categories = getCategories();
    const foldState = getMyVar(MY_RULE.group, CONFIG.FOLD_DEFAULT);
    const currentCate = JSON.parse(getMyVar(MY_RULE.title, JSON.stringify(CONFIG.INIT_CATE)));

    if (parseInt(MY_PAGE) === 1) {
