const templateCache = {
    get(pageType) {
        return getVar(`cache_${pageType}`);
    },
    set(pageType, templateName) {
        putVar(`cache_${pageType}`, templateName);
    },
    clear(pageType) {
        putVar(`cache_${pageType}`, '');
    }
};

// 1. 定义一级页面规则
const primaryRules = {
    "stui-vodlist": {
        list: ".stui-vodlist&&li",
        title: "a&&title",
        desc: ".pic-text&&Text",
        img: ".lazyload||a&&data-original",
        url: "a&&href"
    },
    "myui-vodlist": {
        list: ".myui-vodlist&&li",
        title: "h4&&Text",
        desc: ".pic-tag||.pic-text&&Text",
        img: ".lazyload&&data-original",
        url: "a&&href"
    },
    "vodlist": {
        list: ".vodlist&&li",
        title: "a&&title",
        desc: "a&&Text",
        img: ".lazyload&&data-original",
        url: "a&&href"
    },
    "pack-ykpack": {
        list: "body&&.pack-ykpack",
        title: "a&&title",
        desc: "span,-1&&Text",
        img: ".eclazy&&data-original",
        url: "a&&href"
    },
    "module-items": {
        list: "body&&.module-item",
        title: "strong||a&&Text||title",
        desc: ".module-item-text||.module-item-note&&Text",
        img: "img||.lazy&&data-src||data-original||src",
        url: "a&&href"
    },
    "fed-list-title": {
        list: ".fed-list-info&&li",
        title: ".fed-list-title&&Text",
        desc: ".fed-text-center&&Text",
        img: "a&&data-original",
        url: "a&&href"
    },
    "data_list": {
        list: "#data_list&&li",
        title: "a&&title",
        desc: "em&&Text",
        img: "img&&data-src",
        url: "a&&href"
    }
};

// 2. 创建模板处理函数
function createPrimaryTemplate(config) {
    return {
        list: config.list,
        getData(item) {
            return {
                title: pdfh(item, config.title),
                desc: config.desc ? pdfh(item, config.desc) : undefined,
                img: pd(item, config.img) + "@Referer=",
                url: pd(item, config.url) + "#immersiveTheme#"
            };
        }
    };
}

// 3. 一次性创建所有一级模板
const primaryTemplates = Object.fromEntries(
    Object.entries(primaryRules).map(([key, config]) => [key, createPrimaryTemplate(config)])
);

// 4. 增强的自动匹配函数（整合缓存和自动重试）
function autoPage(htmlsrc, customTemplate, type) {
    const htmlSource = htmlsrc;
    const pageType = type || MY_TYPE;
    let result = [];
    let matchedTemplateName = '';
    
    // 0. 如果提供了自定义模板，优先处理自定义模板
    if (customTemplate && typeof customTemplate === 'object') {
        try {
            // 创建临时模板实例
            const tempTemplate = createPrimaryTemplate(customTemplate);
            const customItems = pdfa(htmlSource, tempTemplate.list);
            
            if (customItems.length > 0) {
                result = customItems.map(item => tempTemplate.getData(item));
                matchedTemplateName = 'custom-template';
                log(`使用自定义模板成功，匹配到 ${customItems.length} 个项目`);
            } else {
                log(`自定义模板未匹配到任何项目，尝试自动匹配...`);
            }
        } catch (e) {
            log(`自定义模板处理失败: ${e.message}，尝试自动匹配...`);
        }
    }
    
    // 1. 如果自定义模板未提供或未匹配到项目，尝试读取缓存
    if (result.length === 0) {
        const cachedTemplateName = templateCache.get(pageType);
        if (cachedTemplateName) {
            try {
                const cachedTemplate = primaryTemplates[cachedTemplateName];
                const cachedItems = pdfa(htmlSource, cachedTemplate.list);
                
                if (cachedItems.length > 0) {
                    result = cachedItems.map(item => cachedTemplate.getData(item));
                    matchedTemplateName = cachedTemplateName;
                    log(`使用缓存模板成功: ${matchedTemplateName}`);
                } else {
                    throw new Error(`缓存模板 ${cachedTemplateName} 无效`);
                }
            } catch (e) {
                log(`缓存模板验证失败: ${e.message}, 开始重新匹配...`);
                templateCache.clear(pageType);
            }
