function dageDecrypt(s) {
    if (!s || typeof s != 'string') return null;
    var t = s.replace(/\//g, '0').replace(/@/g, '/').replace(/\./g, '+');
    t = t.split('').reverse().join('');
    var pad = t.length % 4;
    if (pad != 0) t = t + '===='.substring(0, 4 - pad);
    try { return JSON.parse(base64Decode(t)); } catch (err) { return null; }
}

function dageApi(path) {
    var html = fetch(host + path, {
        headers: {
            'User-Agent': MOBILE_UA,
            'Accept': 'application/json',
            'Cookie': 'x-index-auth=authed',
            'Referer': host + '/'
        }
    });
    try {
        var j = JSON.parse(html);
        if (j && j.status == 1 && j.data) return dageDecrypt(j.data);
        return null;
    } catch (e) { return null; }
}

function makePlayUrl(vid) {
    var vidStr = String(vid);
    return vidStr + $('').lazyRule(function (input, id) {
        id = id || input;
        if (!id) return 'toast://取链失败:无ID';
        var h = 'https://dage.one';
        var ua = 'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36';
        try { if (typeof MOBILE_UA != 'undefined' && MOBILE_UA) ua = MOBILE_UA; } catch (e0) {}
        function dec(s) {
            if (!s || typeof s != 'string') return null;
            var t = s.replace(/\//g, '0').replace(/@/g, '/').replace(/\./g, '+');
            t = t.split('').reverse().join('');
            var pad = t.length % 4;
            if (pad != 0) t = t + '===='.substring(0, 4 - pad);
            try { return JSON.parse(base64Decode(t)); } catch (err) { return null; }
        }
        function buildPlayUrl(pd) {
            if (!pd || !pd.player || pd.player.length < 1) return '';
            var item = pd.player[0];
            var r = item.play || '';
            if (!r) return '';
            try {
                var now = new Date();
                var yy = now.getFullYear() % 100;
                var day = Math.floor((now - new Date(now.getFullYear(), 0, 1)) / 86400000);
                var tok = base64Encode(String(yy) + String(day)).replace(/=+$/, '');
                var servers = item.servers || [];
                if (servers.length > 0 && tok) {
                    var p = servers.length > 1 ? Math.floor(Math.random() * servers.length) : 0;
                    var pair = servers[p] || servers[0];
                    if (pair && pair.length >= 2) {
                        r = r.split('c21.cdn.dycp444.com').join(tok + pair[0]);
                        r = r.split('c22.cdn.dycp444.com').join(tok + pair[1]);
                    }
                }
            } catch (be) {}
            return r;
        }
        var raw = '';
        try {
            raw = fetch(h + '/api/play/' + id + '.json', {
                headers: {
                    'User-Agent': ua,
                    'Accept': 'application/json',
                    'Cookie': 'x-index-auth=authed',
                    'Referer': h + '/play/' + id + '.html',
                    'Origin': h
                }
            });
        } catch (fe) {
            return 'toast://取链失败:网络';
        }
        if (!raw) return 'toast://取链失败:空响应';
        var jo = null;
        try { jo = JSON.parse(String(raw)); } catch (pe) { return 'toast://取链失败:解析'; }
        if (!jo || jo.status != 1 || !jo.data) return 'toast://取链失败:接口';
        var pd = dec(jo.data);
        if (!pd) return 'toast://取链失败:解密';
        var playUrl = buildPlayUrl(pd);
        if (!playUrl) return 'toast://取链失败:无地址';
        if (playUrl.indexOf('m3u8') >= 0 || playUrl.indexOf('M3U8') >= 0) {
            try {
                var cached = cacheM3u8(playUrl, { headers: { 'User-Agent': ua, 'Referer': h + '/' } });
                if (cached) return cached + '#isVideo=true#isM3u8#';
            } catch (ce) {}
            return playUrl + '#isVideo=true#isM3u8#';
        }
        return playUrl + '#isVideo=true#';
    }, vidStr);
}

